SELECT 'moj-all-verified-judgments-review-002-chunk-178' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"919448c9-cbd4-5b80-938e-6fd71621b28c","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقد -إجارة -باقي قيمة أجرة سيارة -إقرار املدعى عليه -الدفع باإلعسار -دعوى اإلعسار ال تسمع من عليها إال بعد تكليفه بالسداد -احلكم بإلزامه بدفع باقي قيمة أجرة السيارة.","document_number":"34273960","case_number":"34170278","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املوافقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/19","year":"1434","subject":"عقد -إجارة -باقي قيمة أجرة سيارة -إقرار املدعى عليه -الدفع باإلعسار -دعوى اإلعسار ال تسمع من عليها إال بعد تكليفه بالسداد -احلكم بإلزامه بدفع باقي قيمة أجرة السيارة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/7/19 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34273960 :‬‬\n                   ‫َر ْق ُم الدعوى‪34170278 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n           ‫‪ 34296128‬تاريخه‪1434/8/14 :‬هـ‬\n\n\n‫عقــد ‪ -‬إجــارة ‪ -‬باقــي قيمــة أجــرة ســيارة ‪ -‬إقــرار املدعــى عليــه ‪ -‬الدفــع‬\n‫باإلعســار ‪ -‬دعــوى اإلعســار ال تســمع مــن عليهــا إال بعــد تكليفــه‬\n        ‫بالســداد ‪ -‬احلكــم بإلزامــه بدفــع باقــي قيمــة أجــرة الســيارة‪.‬‬\n\n\n\n\n                                                        ‫قاعدة ‪ :‬ال عذر ملن أقر‪.‬‬\n\n\n\n‫ادعــى وكيــل املدعــن بــأن املدعــى عليــه اســتأجر مــن موكليــه ســيارة‬\n‫موصوفــة يف الدعــوى ملــدة محــددة وأجــرة مذكــورة يف الدعــوى وقــد‬\n‫ســلم ملوكليــه جــزء مــن قيمــة األجــرة ولــم يســلم باقــي األجــرة املســتحقة‬\n‫عليــه‪ ،‬لــذا طلــب احلكــم بإلــزام املدعــى عليــه بدفــع املبلــغ املدعــى بــه‬\n‫ملوكليــه‪ ،‬أقــر املدعــى عليــه مبــا جــاء يف الدعــوى جملــة وتفصيــا‬\n‫ودفــع بأنــه معســر عــن الســداد وطلــب إمهالــه إال أن وكيــل املدعــن لــم‬\n‫يصــادق علــى هــذا الدفــع‪ ،‬املدعــى عليــه أقــر باملبلــغ املدعــى بــه وال عــذر‬\n‫ملــن أقــر ودعــوى اإلعســار ال تســمع مــن مدعيهــا إال بعــد تكليفــه بالدفــع‬\n‫اســتظهار ًا حلالــه‪ ،‬قضــت احملكمــة بإلــزام املدعــى عليــه بدفــع املبلــغ‬\n‫املدعــى بــه للمدعــي أصالــة‪ ،‬قنــع وكيــل املدعــن باحلكــم وعــارض‬\n‫عليــه املدعــى عليــه‪ -‬قــررت محكمــة االســتئناف املوافقــة علــى احلكــم‪.‬‬\n\n                                                                                       ‫‪230‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا(‪ )........‬القاضــي يف احملكمــة‬\n      ‫اجلزائيــة باملدينــة املنــورة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n      ‫رئيــس احملكمــة اجلزائيــة باملدينــة املنــورة برقــم ‪ 34170278‬وتاريــخ‬\n      ‫‪1434/04/14‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34908331‬وتاريــخ‬\n      ‫‪1434/04/14‬ه ـ ففــي يــوم األربعــاء املوافــق ‪1434/07/19‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة (‪ )11:30‬وفيهــا حضــر (‪ ).....‬ســعودي اجلنســية مبوجــب‬\n      ‫ا عــن (‪ ).....‬ســعودي‬    ‫الســجل املدنــي رقــم (‪ ).....‬حالــة كونــه وكي ـ ً‬\n      ‫بالســجل املدنــي رقــم (‪).....‬مبوجــب صــك الوكالــة الصــادر مــن كتابــة‬\n      ‫العــدل الثانيــة بجــدة برقــم ‪ 54478‬يف ‪1432/6/15‬ه ـ جلــد رقــم ‪10736‬‬\n      ‫ا عــن (‪)......‬ســعودي بالســجل املدنــي رقــم (‪ ).....‬وعــن‬     ‫واملــوكل وكيـ ً‬\n      ‫(‪)......‬ســعودي بالســجل املدنــي رقــم (‪)......‬وعــن (‪ ).....‬ســعودي بالســجل‬\n      ‫املدنــي رقــم (‪ ).....‬واملشــمولون جميعــا ًبصــك الوكالــة الصــادرة مــن‬\n      ‫كتابــة عــدل الثانيــة بجــده برقــم ‪ 7579‬يف ‪1426/1/21‬ه ـ جلــد ‪3844‬‬\n      ‫ادعــى علــى احلاضــر معــه يف مجلــس احلكــم (‪ ).....‬ســعودي بالســجل‬\n      ‫رقــم (‪ )......‬قائــا يف حتريــر دعــواه إنــه يف تاريــخ ‪1432/8/15‬ه ـ‬\n      ‫اســتأجر املدعــى عليــه مــن موكلــي ســيارة (‪ ).....‬نــوع (‪ ).....‬موديــل (‪).....‬‬\n      ‫لونهــا (‪ ).....‬رقــم اللوحــة (‪ )......‬مــدة مائــة وعشــرون يومــا بإيجــار يومــي‬\n      ‫قــدره مائــة وتســعون ريــا ًال دفــع املدعــى عليــه خمســة آالف وتســعمائة‬\n      ‫مــن اســتحقاق اإليجــار ريــال والباقــي مــن اســتحقاق اإليجــار هــو ســتة‬\n      ‫عشــر ألفــا وتســعمائة ريــال وقــد ســلم الســيارة ملوكلــي عنــد نهايــة املــدة‬\n      ‫وقــد طالــب موكلــي املدعــى عليــه بالدفــع فامتنــع لــذا أطلــب احلكــم‬\n\n‫‪231‬‬\n\f‫ملوكلــي بإلــزام املدعــى عليــه بدفــع املبلــغ املدعــى بــه آنــف الذكــر هــذه‬\n‫دعــواي وبســؤال املدعــى عليــه عمــا جــاء بدعــوى املدعــي وكالــة أجــاب‬\n‫قائــا مــا ذكــره املدعــي وكالــة يف دعــواه صحيــح جملــة وتفصيال ففي‬\n‫التاريــخ املذكــور يف الدعــوى اســتأجرت مــن املدعــي أصالــة الســيارة‬\n‫املذكــورة آنفــا املــدة املبينــة آنفــا يف الدعــوى بإيجــار يومــي قــدره مائــة‬\n‫وتســعون ريــا ًال دفعــت للمدعــي أصالــة مــن اســتحقاق اإليجــار خمســة‬\n‫آالف وتســعمائة ريــال والباقــي مــن اســتحقاق اإليجــار هــو ســتة عشــر‬\n‫ألفــا وتســعمائة ريــال وقــد طالبنــي املدعــي أصالــة بالدفــع فلــم أســتطع‬\n‫أن أدفــع لــه الباقــي مــن اســتحقاق اإليجــار لعســري وأطلــب إنظــاري إلــى‬\n‫ميســرة هكــذا أجــاب وبعرضــه علــى املدعــي وكالــة رد قائــا ال علــم‬\n‫لــي وال موكلــي عــن حــال املدعــى عليــه وموكلــي ال يوافــق علــى إمهالــه‬\n‫فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ومبــا أن املدعــى عليــه صــادق‬\n‫علــى دعــوى املدعــي وكالــة فأقــر باملبلــغ املدعــى بــه وال عــذر ملــن أقــر‬\n‫ومبــا أن املدعــى عليــه دفــع باإلعســار وقــرر املدعــي وكالــة عــدم علمــه‬\n‫وموكلــه عــن حــال املدعــى عليــه ولكــون دعــوى اإلعســار ال تســمع مــن‬\n‫مدعيهــا إال بعــد تكليفــه بالدفــع اســتظهار ًا حلالــه جلميــع مــا ذكــر فقــد‬\n‫حكمــت علــى املدعــى عليــه بدفــع املبلــغ املدعــى بــه للمدعــي أصالــة‬\n‫وقــدره ســتة عشــر ألفــا وتســعمائة ريــال وهــو املبلــغ املتبقــي من اســتحقاق‬\n‫إيجــار الســيارة املبينــة آنفــا للمــدة املذكــورة وبعرضــه قــرر املدعــى عليــه‬\n‫عــدم قناعتــه باحلكــم وطلــب رفعــه إلــى محكمــة االســتئناف بــدون‬\n‫الئحــة اعتراضيــة فأجيــب لطلبــه وقــد ذكــر أن مفــاد اعتراضــه هــو‬\n‫كثــرة التزاماتــه وعجــزه عــن الدفــع وقــد انتهــت اجللســة يف متــام الســاعة‬\n‫(‪ )12:00‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n\n\n                                                                                       ‫‪232‬‬\n\f                                       ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1434/7/19‬ه ــ‪.‬‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪ ،‬فقــد‬\n      ‫جــرى منــا نحــن قضــاة الدائــرة احلقوقيــة الثانيــة مبحكمــة االســتئناف‬\n      ‫يف منطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n      ‫رئيــس احملكمــة اجلزائيــة باملدينــة املنــورة برقــم ‪ 34908331‬وتاريــخ‬\n      ‫‪1434/7/22‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ د‪).....( .‬‬\n      ‫القاضــي باحملكمــة اجلزائيــة باملدينــة املنــورة برقــم ‪ 34273960‬وتاريــخ‬\n      ‫‪1434/7/19‬هــ‪ ،‬املتضمــن دعــوى (‪ ).....‬وكالــة ضــد (‪ ،).....‬وبدراســة‬\n      ‫الصــك وصــورة ضبطــه تقــرر املوافقــة علــى احلكــم‪ .‬واهلل املوفــق وصلــى‬\n                        ‫اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪233‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":230,"source_page_end":233,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"3e05938dfb1fc5eb64744bb2deda2cf827156f00e2ac210666be5a75fa964217","normalized_text_hash":"906ca2c32b4daf48687c2d40904336142f255413c14529dcf4e990c5d3b54244","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p230-34273960"},{"id":"b975b227-0e37-5675-975a-d3e25207c821","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقد -إجارة -املطالبة بإخاء عقار ودفع األجرة -سؤال املدعي عما هو الزم لتحرير دعواه -عجز املدعي عن حترير دعواه -صرف النظر عن الدعوى لعدم حتريرها .","document_number":"34173556","case_number":"3488243","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة الرس","circuit":"الدائرة احلقوقية األولى مبحكمة الاستئناف مبنطقة القصيم رقم","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/28","year":"1434","subject":"عقد -إجارة -املطالبة بإخاء عقار ودفع األجرة -سؤال املدعي عما هو الزم لتحرير دعواه -عجز املدعي عن حترير دعواه -صرف النظر عن الدعوى لعدم حتريرها .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/3/28 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34173556 :‬‬\n                    ‫َر ْق ُم الدعوى‪3488243 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n           ‫‪ 34211143‬تاريخه‪1434/5/12 :‬هـ‬\n\n\n‫عقــد ‪ -‬إجــارة ‪ -‬املطالبــة بإخــاء عقــار ودفــع األجــرة ‪ -‬ســؤال املدعــي‬\n‫عمــا هــو الزم لتحريــر دعــواه ‪ -‬عجــز املدعــي عــن حتريــر دعــواه ‪ -‬صــرف‬\n                                    ‫النظــر عــن الدعــوى لعــدم حتريرهــا ‪.‬‬\n\n\n\n‫املــادة ‪ 63/1‬مــن نظــام املرافعــات الشــرعية ولوائحهــا التنفيذيــة ونصهــا‬\n‫« اذا امتنــع املدعــى عــن حتريــر دعــواه أو عجــز عنــه فعلــى القاضــي أن‬\n‫يحكــم بصــرف النظــر عــن الدعــوى حتــى حتريرهــا ويعامــل مــن لــم‬\n                                               ‫يقنــع بتعليمــات التمييــز»‬\n\n\n\n\n‫ادعــت املدعيــة ضــد املدعــى عليــه وكالــة انــه مســتأجر وطلبــت أخــاء‬\n‫فلــه والدهــا وإلزامــه بدفــع إيجــار ‪ 17‬عــام مــن وفــاة والدها‪،‬طلــب ناظــر‬\n‫القضية من املدعية عما هو الزم لتحرير دعواها قبل استجواب املدعى‬\n‫عليــه وذلــك ببيــان صفتهــا بالدعــوى وصفــة املدعــى عليه‪،‬اســتعدت‬\n‫بتحريــر دعواهــا ثــم يف جلســة أخــرى أجابــت بــأن دعواهــا محــررة ‪،‬‬\n‫بنــاء علــى مــا تقــدم وحيــث أن املدعيــة لــم يتحــرر دعواهــا وبنــاء علــى‬\n‫املــادة ‪ 1/63‬مــن نظــام املرافعــات فقــد صــدر احلكــم بصــرف النظــر‬\n‫عــن الدعــوى حتــى حتريرهــا‪ ،‬قــررت املدعيــة عــدم القناعــة ‪ ،‬قــرر‬\n\n                                                                                   ‫‪234‬‬\n\f      ‫املدعــى عليــه وكالــة القناعــة ‪ ،‬صــدر قــرار محكمــة االســتئناف‬\n                             ‫مبنطقــة القصيــم باملصادقــة علــى احلكــم ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا‪ ...........‬القاضــي يف احملكمــة‬\n      ‫العامــة مبحافظــة الــرس وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n      ‫رئيــس احملكمــة العامــة مبحافظــة الــرس برقــم ‪ 3488243‬وتاريــخ‬\n      ‫‪ 1434/02/23‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34449632‬وتاريــخ‬\n      ‫‪ 1434/02/23‬ه ـ ففــي يــوم الســبت املوافــق ‪ 1434/03/07‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪ 08 : 30‬وفيهــا حضــرت ‪...........‬ســعودية‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم‪ ...........‬واملعرفــة مــن ‪...........‬‬\n      ‫ســعودي بالســجل املدنــي رقــم‪ ...........‬وادعــت علــى احلاضــر ‪...........‬‬\n      ‫ا عــن ‪...........‬‬‫ســعودي بالســجل املدنــي رقــم‪ ...........‬بصفتــه وكي ـ ً‬\n      ‫ســعودي بالســجل املدنــي رقــم‪ ...........‬مبوجــب الوكالــة الصــادرة مــن‬\n      ‫كتابــة عــدل محافظــة الــرس برقــم وتاريــخ ‪1434/03/02‬ه ـ وتخــول‬\n      ‫الوكيــل املطالبــة واملرافعــة واملدافعــة واملخاصمــة وإنهــاء مــا يلــزم‬\n      ‫حضــور موكلــه يف كل دعــوى تقــام منــه أو ضــده أمــام أي محكمــة‬\n      ‫واإلقــرار واإلنــكار والصلــح والتنــازل وســماع الدعــوى والــرد عليهــا‬\n      ‫وقبــول احلكــم واالعتــراض عليــه مرفــق صورتــه باملعاملــة قائلــة يف‬\n      ‫دعواهــا (أطلــب إخــاء فلــة والــدي وإلزامــه بدفــع إيجــار ‪ 17‬عــام بعــد‬\n      ‫وفــاة والــدي رحمــه اهلل واتضــح لنــا أنــه يســتلم مبلــغ وقــدره ‪ 21500‬مــن‬\n      ‫الضمــان االجتماعــي بحجــة أنــه مســتأجر وأطلــب إحضــار املدعــى عليــه‬\n      ‫وإلزامــه بإخــاء العقــار وبيعــه عــن طريــق محكمــة الــرس وإلزامــه‬\n\n‫‪235‬‬\n\f‫ـاء علــى املــادة‬\n               ‫بدفــع اإلجــار ) هكــذا ادعــت باللفــظ الــذي نطقــت بــه وبنـ ً‬\n‫رقــم ‪ 63‬مــن نظــام املرافعــات الشــرعية ونصهــا ( علــى القاضــي أن يســأل‬\n‫املدعــي عمــا هــو الزم لتحريــر دعــواه قبــل اســتجواب املدعــى عليــه وليس‬\n‫لــه ردهــا لتحريرهــا وال الســير فيهــا قبــل ذلــك ) أه ـ لــذا فقــد طلبــت مــن‬\n‫املدعيــة حتريــر دعواهــا وذلــك ببيــان صفتهــا بالدعــوى وصفــة املدعــى‬\n‫عليــه وهــل املدعــى عليــه مســتأجر العقــار املذكــور ومــن ميلــك العقــار‬\n‫املذكــور ومقــدار األجــرة التــي تطلبهــا فأجابــت بقولهــا أنــا مســتعدة‬\n‫بتحريــر الدعــوى يف جلســة قادمــة هكــذا أجابــت ورفعــت اجللســة‬\n‫لذلــك إلــى يــوم الســبت املوافــق ‪1434/03/28‬ه ـ الســاعة ‪ 11.00‬ويف‬\n‫يــوم الســبت املوافق‪1434/03/28‬ه ـ افتتحــت اجللســة الســاعة ‪11 : 00‬‬\n‫وفيهــا حضــرت املدعيــة واملدعــى عليــه وكالــة املذكوريــن يف اجللســة‬\n‫االولــى وأطلعــت يف هــذه اجللســة على أصل الوكالــه املذكورة واملدعية‬\n‫معرفــة مــن ســعودي بالســجل املدنــي رقــم وبســؤال املدعيــة عــن حتريــر‬\n‫دعواهــا أجابــت بقولهــا أطلــب منكــم الكتابــة للضمــان االجتماعــي‬\n‫لإلستفســار هــل املدعــى عليــه أصالــه مســتأجر الفلــه املذكــورة أو ال‬\n‫هكــذا أجابــت فطلبــت منهــا حتريــر الدعــوى وذلــك ببيــان مــا ذكــر‬\n‫يف اجللســة األولــى فاجابــت بقولهــا الدعــوى املذكــورة محــرره هكــذا‬\n‫أجابــت ومبــا أن املدعيــة لــم حتــرر دعواهــا وبنــاء علــى املــادة رقــم ‪1/63‬‬\n‫مــن نظــام املرافعــات الشــرعية ولوائحــة التنفيذيــة ونصهــا ( إذا امتنــع‬\n‫املدعــي عــن حتريــر دعــواه أو عجــز عنــه فعلــى القاضــي أن يحكــم‬\n‫بصــرف النظــر عــن الدعــوى حتــى حتريرهــا ويعامــل مــن لــم يقنــع‬\n                                                       ‫بتعليمــات التمييــز ) أ‪.‬ه ـ‬\n‫وبنــاء عليــه حكمــت بصــرف النظــر عــن الدعــوى حتــى حتريرهــا‬\n\n\n                                                                                       ‫‪236‬‬\n\f      ‫وبعــد النطــق باحلكــم وتالوتــه عليهمــا أفهمتهمــا بطــرق اإلعتــراض‬\n      ‫املقــرره ومواعيدهــا فقــرر املدعــى عليــه وكالــه قناعتــه وقــررت‬\n      ‫املدعيــة عــدم قناعتهــا وأفهمتهــا مبراجعتنــا هــذا اليــوم الســبت املوافــق‬\n      ‫‪1434/03/28‬ه ـ الســاعة ‪ 11 : 45‬الســتالم نســخة مــن صــك احلكــم‬\n      ‫وتقــدمي مذكــرة اعتراضيــة إلــى إدارة احملكمــة خــال مــدة أقصاهــا‬\n      ‫ثالثــون يومــا مــن تاريــخ اليــوم وإذا انتهــت املــدة ولــم تتقــدم باعتراضهــا‬\n      ‫فــإن حقهــا يف طلــب االســتئناف يســقط ويكتســب احلكــم القطعــة‬\n      ‫وأختتمــت اجللســة الســاعة ‪ 11 : 20‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n        ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/03/28‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد يف هــذا اليــوم الثالثــاء املوافــق ‪1434/05/21‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪ 01 : 30‬واملعاملــة قــد عــادت مــن محكمــة‬\n      ‫االســتئناف بالقصيــم وقــد مت التظهيــر علــى صــك احلكــم بقــرار‬\n      ‫الدائــرة احلقوقيــة األولــى مبحكمــة االســتئناف مبنطقــة القصيــم رقــم‬\n      ‫‪ 34211143‬وتاريــخ ‪1434/5/12‬ه ـ نصــه ( تظهيــرات الدائــرة احلقوقيــة‬\n      ‫األولــى مبحكمــة االســتئناف مبنطقــة القصيــم احلمــد هلل وحــده وبعــد‬\n      ‫فقــد اطلعنــا علــى هــذا الصــك رقــم ‪ 34173556‬وتاريــخ ‪1434/3/28‬ه ـ‬\n      ‫الصــادر مــن فضيلــة الشــيخ‪ ....... /‬وأصدرنــا القــرار رقــم ‪34211143‬‬\n      ‫وتاريــخ ‪1434/5/12‬ه ـ املتضمــن املصادقــة علــى احلكــم) قاضــي‬\n      ‫اســتئناف قاضــي اســتئناف رئيــس الدائــرة د‪ )/‬أ‪ .‬ه ـ واختتمــت اجللســة‬\n      ‫الســاعة ‪ 01 : 40‬وحــرر يف ‪1434/5/21‬ه ـ وبــاهلل التوفيــق وصلــى اهلل‬\n                                    ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى نبينــا محمــد وعلى آلــه وصحبه‬\n      ‫وبعــد‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة احلقوقيــة األولــى مبحكمــة‬\n\n\n‫‪237‬‬\n\f‫االســتئناف مبنطقــة القصيــم علــى املعاملــة الــواردة مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة بالــرس برقــم (‪ )34449632‬وتاريــخ ‪1434/4/22‬هــ؛‬\n‫احملالــة إلينــا برقــم (‪ )34193204‬؛ املرفــق بهــا الصــك املســجل‬\n‫برقــم (‪ )34173556‬وتاريــخ ‪1434/3/28‬ه ـ ؛ الصــادر مــن فضيلــة‬\n‫الشــيخ‪...........‬القاضي باحملكمــة؛ اخلـ ـ ــاص بدعــوى‪ ............‬ضد‪...........‬‬\n‫بالوكالــة عــن‪ ...........‬؛ بشــأن املطالبــة بإخــاء فلــة وإلزامــه بدفــع‬\n‫األجــرة ملــدة ســبعة عشــر عام ـاً‪ ،‬وقــد تضمــن الصــك حكــم فضيلتــه‬\n‫بصــرف النظــر عــن الدعــوى حتــى حتريرهــا؛ علــى النحــو املفصــل فيــه‪.‬‬\n‫وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة‬\n‫فإننــا نقــرر املصادقــة علــى احلكــم‪ .‬واهلل املوفــق‪ ،‬وصلــى اهلل علــى نبينــا‬\n                                              ‫محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                     ‫‪238‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":234,"source_page_end":238,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"fbd02fc67f88266d7d0ceb20939e2fab3a64a426b12c4a6d3e51d8ed229419c3","normalized_text_hash":"ba28780c5b0b168d501729c78a56f4e1093c5aed5621ee90b3dec209d0bac3e2","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p234-34173556"},{"id":"779f0589-37ba-5761-aa4d-7c6be996b086","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقد -إجارة -مطالبة املستثمر من املستأجر إخاء للعقار -انتهاء العقد باألخطار وفق ما ورد ببنوده -احلكم بإخاء العقار وتسليمه","document_number":"34176933","case_number":"3457987","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باملدينة املنورة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/2","year":"1434","subject":"عقد -إجارة -مطالبة املستثمر من املستأجر إخاء للعقار -انتهاء العقد باألخطار وفق ما ورد ببنوده -احلكم بإخاء العقار وتسليمه","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫تاريخه‪1434/4/2 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34176933 :‬‬\n                          ‫َر ْق ُم الدعوى‪3457987 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                ‫‪ 342225891‬تاريخه‪1434/5/28 :‬هـ‬\n\n\n      ‫عقــد ‪ -‬إجــارة ‪ -‬مطالبــة املســتثمر مــن املســتأجر إخــاء للعقــار ‪ -‬انتهاء‬\n      ‫العقــد باألخطــار وفــق مــا ورد ببنــوده ‪ -‬احلكــم بإخــاء العقــار وتســليمه‬\n                                                                           ‫للمدعى‬\n\n\n\n\n                                   ‫قوله تعالى « يا أيها الذين امنوا أوفوا بالعقود»‬\n\n\n\n\n      ‫ادعــى املدعــى وكالــة ضــد املدعــى عليــه وكالــة بــان املدعــى عليــه‬\n      ‫ا جتاري ـ ًا يف عمارتــه ملــدة‬\n                                    ‫أصالــة قــد اســتأجر مــن املدعــى أصالــة مح ـ ً‬\n      ‫ســنة بأجــرة ســنوية قدرهــا أربعــة وثالثــون ألــف ريــال ويتجــدد العقــد‬\n      ‫تلقائي ـ ًا مــا لــم يخطــر أحــد الطرفــن الطــرف اآلخــر بعــدم الرغبــة يف‬\n      ‫التجديــد قبــل انتهــاء العقــد بشــهرين وقــد مت أخطــار املدعــى عليــه بعــدم‬\n      ‫الرغبــة يف التجديــد قبــل انتهــاء العقــد بشــهرين ولكــن املدعــى عليــه لــم‬\n      ‫يخــل احملــل وطلــب املدعــى وكالــة إلــزام املدعــى عليــه بإخــاء احملــل‪،‬‬\n      ‫أجــاب املدعــى عليــه باملصادقــة علــى الدعــوى جملــة وتفصيــا وذكــر‬\n      ‫انــه ال يســتطيع اإلخــاء يف الوقــت احلالــي الن احملــل مؤجــر علــى موكله‬\n      ‫منــذ خمســة وعشــرين عامــا وان لديــة قاعــدة عمــاء مرتبطــة باحملــل وان‬\n      ‫املدعــى أصالــة ليــس املالــك للعقــار وإمنــا مســتثمر وأنــه ال مانــع لديــه مــن‬\n\n‫‪239‬‬\n\f‫زيــادة األجــرة‪ ،‬أصــر املدعــى وكالــة علــى طلــب اإلخــاء‪ ،‬مت اطــاع‬\n‫ناظــر القضيــة علــى العقــد بــن الطرفــن فوجــده كمــا ذكــر املدعــى‬\n‫وكالــة ومت إرفاقــه باملعاملــة ‪ ،‬بنــاء علــى مــا تقــدم وملصادقــة املدعــى‬\n‫عليــه بــان املدعــى أصالــة هــو املالــك للمنفعــة واملســتثمر للعقــار وأن‬\n‫العقــد ســنوي وقــد اقــر بــان املدعــى اخطــره قبــل نهايــة العقــد بشــهرين‬\n‫بعــدم الرغبــة يف التجديــد فقــد صــدر احلكــم علــى املدعــى عليــه بإخــاء‬\n‫العقــار وتســليمه للمدعــى قنــع املدعــى ولــم يقنــع املدعــى عليــه ‪ ،‬صــدر‬\n‫قــرار محكمــة االســتئناف مبكــة املكرمــة باملصادقــة علــى احلكــم ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا‪ ...........‬القاضــي يف احملكمــة‬\n‫العامــة باملدينــة املنــورة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n‫رئيــس احملكمــة العامــة باملدينــة املنــورة برقــم ‪ 3457987‬وتاريــخ‬\n‫‪1434/02/04‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34289554‬وتاريــخ‬\n‫‪1434/02/04‬ه ـ ففــي يــوم الثالثــاء املوافــق‪ 1434/03/03‬ه ـ افتتحت‬\n‫اجللســة الســاعة الثامنــة والنصــف وفيهــا حضــر ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم الوكيــل الشــرعي عــن مبوجــب الوكالــة‬\n‫الصــادرة مــن كتابــة عــدل املدينــة املنــورة الثانيــة برقــم ‪ 3447007‬يف‬\n‫‪1434/01/13‬هــ‪ ،‬وادعــى علــى احلاضــر معــه يف مجلس احلكــم ‪...........‬‬\n‫ســعودي اجلنســية مبوجب الســجل املدني رقم‪ ...........‬الوكيل الشــرعي‬\n‫عــن ‪...........‬ســعودية اجلنســية مبوجــب الســجل املدنــي رقــم‪...........‬‬\n‫مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل املدينــة املنــورة الثانيــة‬\n‫ا يف دعــواه عليــه ‪ :‬لقــد اســتأجر‬ ‫برقــم ‪ 3541‬يف ‪1427/01/21‬هــ‪ ،‬قائـ ً‬\n\n                                                                                      ‫‪240‬‬\n\f      ‫املدعــى عليــه مــن موكلــي احملــل التجــاري يف العمــارة الواقعــة علــى‬\n      ‫شــارع ‪..........‬يف املدينــة املنــورة ملــدة ســنة ابتــداء مــن ‪1433/01/01‬هــ‪،‬‬\n      ‫بأجــرة ســنوية قدرهــا أربعــة وثالثــون ألــف ريــال ويتجــدد العقــد تلقائيـ ًا‬\n      ‫مــا لــم يخطــر أحــد الطرفــن الطــرف اآلخــر بعــدم الرغبــة يف التجديــد‬\n      ‫قبــل انتهــاء العقــد بشــهرين ونظــر ًا لرغبــة موكلــي يف احملــات التجارية‬\n      ‫فقــد مت إخطــار املدعــى عليــه بتاريــخ ‪1433/10/18‬هــ‪ ،‬بعــدم الرغبــة‬\n      ‫يف التجديــد للعــام ‪1434‬هــ‪ ،‬وحتــى تاريــخ هــذا اليــوم واملدعــى عليــه لــم‬\n      ‫يقــم بإخــاء احملــل أطلــب احلكــم بإلزامــه بذلــك هــذه دعــواي وبســؤال‬\n      ‫املدعــى عليــه عمــا جــاء يف دعــوى املدعــي أجــاب بقولــه مــا ذكــره‬\n      ‫ا إال أننــي ال أســتطيع‬   ‫املدعــي يف دعــواه كلــه صحيــح جمل ـ ًة وتفصي ـ ً‬\n      ‫اإلخــاء يف الوقــت احلالــي لكونــي مســتأجر منــذ خمســة وعشــرين‬\n      ‫ـدي قاعــدة عمــاء مرتبطــة بهــذا املوقــع واملدعــي ليــس مالــك‬         ‫ســنة ولـ ّ‬\n      ‫ـدي مــن الزيــادة يف‬‫للعقــار وإمنــا مســتثمر مــن املالــك وهــي ‪ .......‬وال مانــع لـ ّ‬\n      ‫األجــرة مبلــغ خمســة آالف ريــال ألن يف إخــاء احملــل خســارة علـ ّـي هــذه‬\n      ‫إجابتــي وبعــرض ذلــك علــى املدعــي قــال إن موكلــي مصـ ّـر علــى طلــب‬\n      ‫اإلخــاء هكــذا قــال ويف جلســة أخرى مؤرخــة يف ‪1434/4/2‬هـ حضر‬\n      ‫الطرفــان وأبــرز املدعــي عقــد اإليجــار بينــه وبــن املدعــى عليــه فوجدتــه‬\n      ‫كمــا ذكــر املدعــي ومت إرفاقــه باملعاملــة ‪ ،‬كمــا أبــرز املدعــى عليــه‬\n      ‫ـاء علــى‬‫ســندي قبــض ألجــرة عــام ‪1433‬ه ـ ومت إرفاقهــا باملعاملــة ‪ ،‬فبنـ ً‬\n      ‫مــا تقــدم مــن الدعــوى واإلجابــة وملصادقــة املدعــى عليــه املدعــي يف‬\n      ‫دعــواه وإلقــراره بــأن املدعــي هــو املالــك للمنفعــة واملســتثمر للعقــار وأن‬\n      ‫مــدة العقــد ســنة كاملــة تتجــدد تلقائيــا مــا لــم يخطــر أحــد الطرفــن‬\n      ‫الطــرف األخــر بعــدم الرغبــة يف التجديــد وقــد أقــر املدعــى عليــه بــأن‬\n\n\n‫‪241‬‬\n\f‫املدعــي قــد أخطــره بتاريــخ ‪1433/10/18‬ه ـ بعــدم الرغبــة يف التجديــد‬\n‫وألن املســتأجر حقيقــة مالــك للمنفعــة ولقــول اهلل ســبحانه وتعالــى (( يــا‬\n‫أيهــا اللذيــن آمنــوا أوفــوا بالعقــود )) لذلــك كلــه فقــد حكمــت علــى‬\n‫املدعــى عليــه بإخــاء العقــار محــل الدعــوى وتســليمه للمدعــي وبعــرض‬\n‫احلكــم علــى الطرفــن قــرر املدعــي قناعتــه وقــرر املدعــى عليــه وكالــة‬\n‫عــدم القناعــة مســتعدا بتقــدمي الئحــة اعتراضيــة فأجيــب لطلبــه وأفهــم‬\n‫باالنتظــار نصــف ســاعة الســتالم نســخة احلكــم وســوف يحتســب بعــد‬\n‫ذلــك مهلــة ثالثــن يومــا إذا لــم يقــدم املدعــى عليــه اعتراضــه خاللهــا‬\n‫ســقط حقــه يف تدقيــق احلكــم واكتســب القطعيــة وقــرر املدعــى عليــه‬\n‫وكالــة اســتالمه نســخة مــن احلكــم لتقــدمي اعتراضــه عليــه‪ ،‬وبــاهلل‬\n‫التوفيــق وصلــى اهلل وبــارك علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n                                                      ‫حــرر يف ‪1434/4/2‬هــ‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪ ،‬فقــد‬\n‫جــرى منــا نحــن قضــاة الدائــرة احلقوقيــة الثانيــة مبحكمــة االســتئناف‬\n‫يف منطقــة مكــة املكرمــة اإلطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n‫رئيــس احملكمــة العامــة باملدينــة املنــورة برقــم ‪ 34/289554‬وتاريــخ‬\n‫‪1434/4/27‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ‪...........‬‬\n‫القاضــي باحملكمــة العامــة باملدينــة املنــورة برقــم ‪ 34176933‬وتاريــخ‬\n‫‪1434/4/2‬ه ـ ‪ ،‬املتضمــن دعــوى ‪ ...........‬ضــد‪ ، ...........‬وبدراســة‬\n‫الصــك وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر باألكثريــة املوافقــة‬\n‫علــى احلكــم‪ .‬واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى‬\n                                                            ‫آلــه وصحبــه وســلم‪.‬‬\n\n\n\n                                                                                    ‫‪242‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":239,"source_page_end":242,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"dc771b24e5380c5ff9894f6f51fc1a9a09e2ebf2b96f572fdaf082e2a36e0262","normalized_text_hash":"a091a671de9f5ec66955baaad5c5a9f3ba00d732bd5aaa04f1c283930a7fab4d","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p239-34176933"},{"id":"abb4a8c8-ada0-5237-90e0-64b307e40172","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقد -إجارة -إخاء عقار -عدم التقيد بشرط غير منصوص عليه يف العقد -األخذ بالقرائن على إثبات الرضا بالعقد -األخذ بالقرائن على نفي دعوى عدم التقيد بشرط غير منصوص عليه يف العقد -احلكم بتسليم العن للمدعى.","document_number":"34184071","case_number":"33641157","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باخلبر","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1432/4/9","year":"1434","subject":"عقد -إجارة -إخاء عقار -عدم التقيد بشرط غير منصوص عليه يف العقد -األخذ بالقرائن على إثبات الرضا بالعقد -األخذ بالقرائن على نفي دعوى عدم التقيد بشرط غير منصوص عليه يف العقد -احلكم بتسليم العن للمدعى.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫تاريخه‪1432/4/9 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34184071 :‬‬\n                         ‫َر ْق ُم الدعوى‪33641157 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                 ‫‪ 34305248‬تاريخه‪1434/8/24 :‬هـ‬\n\n\n      ‫عقــد ‪ -‬إجــارة ‪ -‬إخــاء عقــار ‪ -‬عــدم التقيــد بشــرط غيــر منصــوص‬\n      ‫عليــه يف العقــد ‪ -‬األخــذ بالقرائــن علــى إثبــات الرضــا بالعقــد ‪ -‬األخــذ‬\n      ‫بالقرائــن علــى نفــي دعــوى عــدم التقيــد بشــرط غيــر منصــوص عليــه‬\n                                 ‫يف العقــد ‪ -‬احلكــم بتســليم العــن للمدعــى‪.‬‬\n\n\n\n\n                       ‫ين َآ َم ُنوا َأوْفُ وا ِبا ْل ُع ُقو ِد ﴾‬\n                                                               ‫‪ -1‬قوله تعالى ﴿ َيا َأ ُّي َها ا َّلذِ َ‬\n      ‫‪ -2‬قولــه صلــى اهلل عليــه وســلم « املســلمون علــى شــروطهم إال شــرط ًا‬\n                                                                 ‫أحــل حرام ـ ًا أو حــرم حــاالً»‬\n\n\n\n\n      ‫ادعــى املدعــى بــأن املدعــى عليــه اســتأجر منــه عمــارة موصوفــة يف نــص‬\n      ‫القضيــة ملــدة خمــس ســنوات مــن ‪ 1430/6/1‬ه ـ بأجــرة ســنوية قدرهــا‬\n      ‫مائــة وســبعون ألــف ريــال وان املدعــى عليــه تخلــف عن ســداد األجرة منذ‬\n      ‫شــهر جمــاد اآلخــر عــام ‪ 1432‬ه ـ وصــدر عليــه حكــم بدفــع األجــرة وهو‬\n      ‫لــم يدفــع حتــى اآلن وطلــب املدعــى إلــزام املدعــى عليــة بإخــاء العقــار‬\n      ‫وذلــك حلصــول شــرط ينــص علــى تخويــل املدعــى باملطالبــة باإلخــاء عند‬\n      ‫حصــول تقصيــر مــن املدعــى عليــه بدفــع األجــرة ‪ ،‬أجــاب املدعــى عليــه‬\n      ‫باملصادقــة علــى الدعــوى ودفــع أن بينــه وبــن املدعــى شــرط ًا يتضمــن‬\n\n‫‪243‬‬\n\f‫التزامــه بإصــدار تراخيــص جلميــع شــقق العمــارة وهــو لــم يلتــزم بذلــك‬\n‫ولــذا قــرر أنــه توقــف عــن تســليم األجــرة‪ ،‬انكــر املدعــى هــذا الشــرط‪،‬‬\n‫قــرر املدعــى عليــه انــه لــم يقــم بإقامــة شــكوى بشــأن هــذا الشــرط‬\n‫املدعــى بــه‪ ،‬عــدم وجــود بينــة للمدعــى عليــه علــى هــذا الشــرط ‪ ،‬رفــض‬\n‫املدعــى عليــة ميــن املدعــى علــى نفــي الشــرط ‪ ،‬قــرر ناظــر القضيــة انــه‬\n‫بنــاء علــى الدعــوى واإلجابــة ومبــا أن املدعــى عليــه لــم يقــم بشــكاية‬\n‫املدعــى عنــد عــدم جتاوبــه ومــازال يف العمــارة ودفــع أجــرة الســنة األولــى‬\n‫ممــا يــدل علــى رضــاه بالعقــد ولوجــود شــرط منصــوص عليــه يف العقــد‬\n‫يخــول املدعــى باملطالبــة باإلخــاء عنــد حصول تقصير يف تســليم األجرة‬\n‫ولقولــه تعالــى ﴿ َيــا َأ ُّي َهــا الَّذِ يـ َـن آ ََم ُنــوا َأ ْو ُفــوا ِبا ْل ُع ُقــو ِد ﴾ فقــد صــدر‬\n‫احلكــم بإلــزام املدعــى عليــه بإخــاء العقــار موطــن الدعــوى وتســليمه‬\n‫كمــا اســتلمه بعــد تصفيــة فاتورتــي الكهربــاء وامليــاه‪ ،‬وللمدعــى عليــه‬\n‫ميــن املدعــى علــى نفــى مــا دفــع بــه متــى أراد‪ ،‬قــرر املدعــى القناعــة وقــرر‬\n‫املدعــى عليــه عــدم القناعــة‪ ،‬صــدر قــرار محكمــة االســتئناف باملنطقــة‬\n                                                         ‫الشــرقية باملصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا‪ ...........‬القاضــي يف احملكمــة العامــة‬\n‫باخلبــر وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة باخلبــر املكلــف برقــم ‪ 33641157‬وتاريــخ ‪ 1433/11/08‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 331963670‬وتاريخ ‪1433/11/8‬هـ ففي يوم‬\n‫الثالثــاء املوافــق ‪1434/2/12‬ه ـ افتتحــت اجللســة الســاعة ‪ 9:30‬وفيهــا‬\n‫حضــر املدعــي أصالــة ‪...........‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n\n                                                                                                                 ‫‪244‬‬\n\f      ‫رقــم‪ ...........‬ولــم يحضــر املدعــى عليــه مــع تبلغــه مبوعــد اجللســة وإعالنــه‬\n      ‫لشــخصه وقــد قــدم عــذرا بــأن لديــه موعــدا جللســة يف الهيئــة االبتدائيــة‬\n      ‫لتســوية اخلالفــات العماليــة وذلــك يــوم الثالثــاء ‪1434/2/12‬ه ـ الســاعة‬\n      ‫التاســعة صباحــا فطلبــت مــن املدعــي حترير دعواه فادعــى املدعي قائال‬\n      ‫يف دعواه لقد اســتأجر املدعى عليه مني العمارة الواقعة يف شــارع ‪ ...‬يف‬\n      ‫حــي ‪ ...‬واملكونــة مــن اثنــي عشــر جناحـ ًا وكل جنــاح مكــون مــن صالــة‬\n      ‫ـداء مــن ‪1430/6/1‬ه ـ إلــى ‪1435/5/30‬ه ـ‬        ‫وغــرف وبوفيــه وحمــام ابتـ ً‬\n      ‫بأجــرة ســنوية قدرهــا مائــة وســبعون ألــف ريــال وقــد تخلــف عــن ســداد‬\n      ‫األجــرة منــذ شــهر جمــادى اآلخــر لعــام ‪1432‬ه ـ وقــد صــدر عليــه حكــم‬\n      ‫بدفــع أجــرة حتــى ‪1433/11/30‬ه ـ ولــم يدفــع حتــى اآلن لــذا أطلــب‬\n      ‫إلــزام املدعــى عليــه بإخــاء العمــارة وذلــك مبوجــب الشــرط الثالــث‬\n      ‫والــذي يخولنــي املطالبــة باإلخــاء حلصــول التقصيــر مــن املدعــى عليــه‬\n      ‫بدفــع األجــرة هــذه دعــواي وبســؤال املدعــي عــن صــك العقــار وعقــد‬\n      ‫اإليجــار أجــاب قائــا لــم أحضــره وأطلــب إمهالي إلحضارهما يف اجللســة‬\n      ‫القادمــة هكــذا أجــاب وطلــب فأجبتــه لطلبــه وعليــه رفعــت اجللســة‬\n      ‫الســاعة العاشــرة لتمكــن املدعــي مــن إحضــار صــك العقــار وعقــد‬\n      ‫اإليجــار ويف جلســة أخــرى حضــر املدعــي كمــا حضــر املدعــى عليــه‬\n      ‫‪...........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‪ ...........‬وبعــرض‬\n      ‫دعــوى املدعــي املرصــودة يف اجللســة املاضيــة علــى املدعــى عليــه أجــاب‬\n      ‫قائ ـاً‪ :‬مــا ذكــره املدعــي يف دعــواه صحيــح بخصــوص اســتئجاري‬\n      ‫منــه العمــارة املوصوفــة بالدعــوى والواقعــة يف شــارع ‪ ...‬يف حــي ‪ ...‬مــن‬\n      ‫‪1430/6/1‬ه ـ إلــى ‪1435/5/30‬ه ـ بأجــرة ســنوية قدرهــا مائــة وســبعون‬\n      ‫ألــف ريــال وصحيــح بأننــي توقفــت عــن دفــع األجــرة يف شــهر جمــادى‬\n\n\n‫‪245‬‬\n\f‫اآلخــر لعــام ‪1432‬ه ـ لعــدم وفائــه بالعقــد الــذي بينــي وبينــه وذلــك بعــدم‬\n‫إصــدار ترخيــص جلميــع الشــقق وإمنــا مت إصــدار ترخيــص لســتة شــقق‬\n‫هكــذا أجــاب وبعــرض ذلــك علــى املدعــي أجــاب قائ ـاً‪ :‬لقــد أجرتــه‬\n‫اثنــا عشــرة شــقة ولســت مســؤو ًال عــن إصــدار الترخيــص مــن عدمهــا‬\n‫ولــم يحصــل اتفــاق بيننــا علــى إصــدار الترخيــص هكــذا أجــاب فجــرى‬\n‫ســؤال املدعــى عليــه هــل لديــك بينــة علــى وجــود اتفــاق مــع املدعــي علــى‬\n‫إصــدار الترخيــص جلميــع الشــقق أو اشــتراط ذلــك عليــه فأجــاب قائـاً‪:‬‬\n‫ليــس لــدي بينــة علــى ذلــك غيــر أنــه ســلمني أوراق البلديــة أن املوقــع‬\n‫مالئــم ملزاولــة النشــاط واشــترط علــي جتهيــزات الدفــاع املدنــي هكــذا‬\n‫أجــاب ثــم جــرى ســؤاله هــل أقمــت علــى املدعــي شــكوى أو دعــوى‬\n‫فأجــاب قائ ـاً‪ :‬ال لــم أقــم شــكوى أو دعــوى حيــث وعدنــي بتصحيــح‬\n‫األوضــاع ثــم بادرنــي بالشــكوى يف احملكمــة هكــذا أجــاب ثــم جــرى‬\n‫ا‬‫ســؤاله متــى توقفــت عــن ســداد األجــرة مــن تاريــخ العقــد فأجــاب قائـ ً‬\n‫بعــد مضــي ســنة مــن تاريخــه هكــذا أجــاب فجــرى إفهــام املدعــى عليــه‬\n‫بــأن لــك ميــن املدعــي علــى نفــي مــا دفعــت بــه فأجــاب قائ ـاً‪ :‬ال أطلــب‬\n‫ميينــه هكــذا أجــاب هــذا وقــد جــرت الكتابــة إلــى كتابــة عــدل اخلبــر‬\n‫األولــى برقــم ‪ 332244559‬يف ‪1433/12/26‬ه ـ بخصــوص االستفســار‬\n‫عــن ســريان مفعــول الصــك رقــم ‪ 325‬يف ‪1403/11/27‬ه ـ واململــوك‬\n‫للمدعــي فوردنــا جوابهــم باخلطــاب رقــم ‪ 34360177‬يف ‪1434/2/12‬ه ـ‬\n‫بأنــه متوافــق مــع ســجله وموقــع ومختــوم مــن ناظــر وســاري املفعــول ا‪.‬ه ـ‬\n‫كمــا قــرر املدعــي قائــا‪ :‬لقــد أحضــرت عقــد اإليجــار رقــم ‪ 17‬يف‬\n‫‪1430/5/4‬ه ـ مــن مطبوعــات ‪ ...‬لتســويق العقــار وفيــه تأجيــر املدعــي‬\n‫للمدعــى عليــه اثنــا عشــرة شــقة والواقعــة علــى شــارع ‪ ...‬يف حــي ‪ ...‬مــدة‬\n\n\n                                                                                     ‫‪246‬‬\n\f      ‫خمــس ســنوات بأجــرة ســنوية قدرهــا مائــة وســبعون الــف ريــال تدفــع‬\n      ‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وحيــث‬      ‫كل ســتة أشــهر فبنـ ً‬\n      ‫صــادق املدعــى عليــه علــى دعــوى املدعــي وعلــى عــدم دفعــه األجــرة يف‬\n      ‫حينهــا ودفــع بــأن الســبب يف عــدم ســداده هــو أن العمــارة غيــر مرخصــة‬\n      ‫مــن البلديــة علــى أنهــا ‪12‬شــقة ومبــا أن العقــد الــذي بــن الطرفــن لــم‬\n      ‫ينــص علــى اســتخراج ترخيــص مــن قبــل املدعــي أو اشــتراطه ومبــا أن‬\n      ‫املدعــى عليــه لــم يقــم بشــكاية املدعــي عنــد عــدم جتاوبــه معــه ومبــا‬\n      ‫أنــه مــا زال يف العمــارة حتــى اآلن ومبــا أنــه دفــع أجــرة الســنة األولــى‬\n      ‫ممــا يــدل علــى رضــاه بالعقــد ومبــا أن املدعــى عليــه البينــة لديــه علــى مــا‬\n      ‫دفــع بــه ومبــا أنــه لــم يقبــل بيمــن املدعــي علــى نفــي مــا دفــع بــه ولقولــه‬\n      ‫تعالــى (يأيهــا الذيــن آمنــوا أوفــو بالعقــود) ولقولــه صلــى اهلل عليــه وســلم‬\n      ‫(املســلمون علــى شــروطهم إال شــرط ًا أحــل حرامـ ًا أو حــرم حــاالً) ومبــا‬\n      ‫أن البنــد الثالــث نــص علــى أن للمؤجــر احلــق يف تكليــف املســتأجر‬\n      ‫بإخــاء املأجــور إذا حصــل مــن املســتأجر تقصيــر يف دفــع اإليجــار ومبــا‬\n      ‫أن املدعــى عليــه قــد أقــر بعــدم دفعــه لألجــرة ومبــا أن املدعــي يطالــب‬\n      ‫بإلــزام املدعــى عليــه بإخــاء العمــارة لذلــك كلــه فقــد ثبــت لــدي أن‬\n      ‫املدعــى عليــه لــم يدفــع األجــرة منــذ شــهر جمــادى األخــر لعــام ‪1432‬ه ـ‬\n      ‫للمدعــي وحكمــت بإلــزام املدعــى عليــه بتســليم العمــارة للمدعــي كما‬\n      ‫اســتلمها بعــد تصفيــة فاتــورة الكهربــاء واملــاء وبذلك حكمــت وافهمت‬\n      ‫املدعــى عليــه بــأن لــه ميــن املدعــي علــى نفــي مــا دفــع بــه متــى طلبهــا‬\n      ‫وبعــرض احلكــم علــى الطرفــن قــرر املدعــي القناعــة بــه كمــا قــرر‬\n      ‫املدعــى عليــه عــدم القناعــة باحلكــم وتقــدمي الئحتــه االعتراضيــة فأفهــم‬\n      ‫بــأن عليــه املراجعــة بعــد ثالثــة أيــام واســتالم نســخة مــن احلكــم وتقــدمي‬\n\n\n‫‪247‬‬\n\f‫الئحتــه االعتراضيــة خــال ثالثــن يــوم مــن تاريــخ تســجيل الصــك ففهــم‬\n‫ذلــك وإنــه إن لــم يتقــدم بشــيء خــال املــدة املشــار إليهــا فــإن حقــه يف‬\n‫االعتــراض يســقط ويكتســب احلكــم القطعيــة وبــاهلل التوفيــق وصلــى‬\n‫اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/4/2‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يوم األحد املوافق ‪1434/10/11‬هـ افتتحت‬\n‫اجللســة الســاعة ‪ 9:30‬هــذا وقــد عــادت املعاملــة من محكمة االســتئناف‬\n‫باملنطقة الشرقية باخلطاب رقم ‪ 341599782‬يف ‪1434/8/28‬هـ مرفق ًا‬\n‫بهــا قــرار املصادقــة مــن الدائــرة احلقوقيــة األولــى برقــم ‪ 34305248‬يف‬\n‫‪1434/8/24‬ه ـ ونصــه بعــد املقدمــة (وبدراســة الصــك وصــورة وأوراق‬\n‫املعاملــة قررنــا املصادقــة علــى احلكــم) قاضــي االســتئناف‪ ...........‬ختمــه‬\n‫وتوقيعــه قاضــي االســتئناف‪ ...........‬ختمــه وتوقيعــه رئيــس الدائــرة‬\n‫‪ ...........‬ختمــه وتوقيعــه وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد‬\n                         ‫وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/10/11‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى رســولنا محمــد و آلــه وصحبــه‬\n‫أمــا بعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة احلقوقيــة األولــى يف‬\n‫محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة مــن‬\n‫فضيلــة رئيــس احملكمــة العامــة مبحافظــة اخلبــر املســاعد املك ّلــف‬\n‫برقــم ‪ 341509795‬وتاريــخ ‪1434/6/21‬ه ـ واملقيــدة لــدى احملكمــة‬\n‫برقــم ‪ 341599782‬وتاريــخ ‪1434/7/2‬ه ـ املرفــق بهــا الصــك الصــادر‬\n‫مــن فضيلــة القاضــي باحملكمــة الشــيخ‪ .........../‬املسـ ّـجل برقــم‬\n‫‪ 34184071‬وتاريــخ ‪1434/4/9‬ه ـ اخلــاص بدعــوى‪ ...........‬ضــد‪...........‬‬\n‫يف قضيــة حقوقيــة وقــد تضمــن الصــك حكــم فضيلتــه مبــا هــو مــدون‬\n‫ومفصــل فيــه ‪ .‬وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة‬\n\n\n                                                                                     ‫‪248‬‬\n\f      ‫وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم ‪ ،‬ولبيانــه حــرر يف‬\n                                   ‫‪1434/8/24‬ه ـ ‪ ،‬واهلل ولــي التوفيــق ‪.‬‬\n\n\n\n\n‫‪249‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":243,"source_page_end":249,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"4a365170f8cd0343532e1a779609928a46a71c0df3ed3f4056ba524eba73aab2","normalized_text_hash":"1f081f38a0d071bb15594011023951d2278ffb446e41df982a0092e1d7e4b56a","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p243-34184071"},{"id":"be3c1091-a5df-57f3-b855-33704ce4ea7b","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقد -إجارة -إجارة وقف -طلب إخاء العقار ودفع األجرة املستحقة -احلكم بلزوم عقد اإلجارة -عدم بطان عقد اإلجارة بوفاة املؤجر ولو كان ناظر وقف -صرف نظر عن مطالبة بإخاء عقار حا ال وعن مطالبة زيادة أجرة -حكم بتسليم أجرة حالة ومتأخرة -حكم بإخاء عقار يف نهاية العقد سليما خاليا من الشواغل بعد إصاح جميع ما فيه -حكم بدفع أجرة مستقبلية يف وقتها احملدد.","document_number":"34184303","case_number":"3347601","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/10","year":"1434","subject":"عقد -إجارة -إجارة وقف -طلب إخاء العقار ودفع األجرة املستحقة -احلكم بلزوم عقد اإلجارة -عدم بطان عقد اإلجارة بوفاة املؤجر ولو كان ناظر وقف -صرف نظر عن مطالبة بإخاء عقار حا ال وعن مطالبة زيادة أجرة -حكم بتسليم أجرة حالة ومتأخرة -حكم بإخاء عقار يف نهاية العقد سليما خاليا من الشواغل بعد إصاح جميع ما فيه -حكم بدفع أجرة مستقبلية يف وقتها احملدد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/4/10 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34184303 :‬‬\n                    ‫َر ْق ُم الدعوى‪3347601 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n           ‫‪ 34236593‬تاريخه‪1434/6/11 :‬هـ‬\n\n\n‫عقــد ‪ -‬إجــارة ‪ -‬إجــارة وقــف‪ -‬طلــب إخــاء العقــار ودفــع األجــرة‬\n‫املســتحقة ‪ -‬احلكــم بلــزوم عقــد اإلجــارة ‪ -‬عــدم بطــان عقــد اإلجــارة‬\n‫بوفــاة املؤجــر ولــو كان ناظــر وقــف ‪ -‬صــرف نظــر عــن مطالبــة بإخــاء‬\n‫عقــار حــا ًال وعــن مطالبــة زيــادة أجــرة ‪ -‬حكــم بتســليم أجــرة حالــة‬\n‫ومتأخــرة ‪ -‬حكــم بإخــاء عقــار يف نهايــة العقــد ســليما خاليــا مــن‬\n‫الشــواغل بعــد إصــاح جميــع مــا فيــه ‪ -‬حكــم بدفــع أجــرة مســتقبلية‬\n                                                          ‫يف وقتهــا احملــدد‪.‬‬\n\n\n\n\n‫«اإلجــارة عقــد الزم وال يبطــل بوفــاة املؤجــر ولــو كان ناظــر الوقف ألنه‬\n‫أجــرة بصفتــه الناظــر علــى وقفــه وهــو قــد اشــترط النظــارة لنفســه»‬\n‫انظــر منتهــى اإلرادات البــن النجــار ‪ 63/5‬وكشــاف القنــاع ‪.75-74/9‬‬\n\n\n\n\n‫ادعــى املدعــى (ناظــر الوقــف) علــى املدعــى عليهمــا أن الواقــف أجــر قبل‬\n‫وفاتــه العقــار لهمــا ملــدة ســنة مــن ‪1431/6/13‬ه ـ حتــى ‪1432/6/12‬ه ـ‬\n‫بأجــرة ســنوية مقــدرة مببلــغ معــن‪ ،‬ولــم يدفعــا هــذه األجــرة ولــم يخليــا‬\n‫العقــار‪ ،‬واحدثــا أضــرار ًا بالغــة به باملخالفة لبنود العقد‪ ،‬وقد مت أخطار‬\n‫املدعــى عليهمــا بضــرورة اإلخــاء بعــد إصالح مــا مت تغيره وزيادة األجرة‬\n\n                                                                                    ‫‪250‬‬\n\f      ‫الســنوية لعــام ‪1433‬ه ـ ‪ ،‬طلــب املدعــى إلــزام املدعــى عليهمــا بدفــع‬\n      ‫األجــرة املتأخــرة مــن ‪1431/6/13‬ه ـ إلــى ‪1432/12/12‬ه ـ ‪.2 ،‬إلــزام‬\n      ‫بدفــع األجــرة احلالــة بتاريــخ ‪1432/12/13‬ه ـ إلــى ‪1433/6/12‬هــ‪،‬‬\n      ‫‪.3‬انتــداب جلنــة اخلبــراء للوقــوف علــى املبنــى ومعاينــة األضــرار والتغيــرات‬\n      ‫التــي أحدثهــا املدعــى عليهمــا‪ .4 ،‬إلــزام املدعــى عليهمــا بدفــع أتعــاب‬\n      ‫ومصاريــف احملامــاة‪ .‬أجــاب وكيــل املدعــى عليهمــا باإلقــرار باإليجــار‬\n      ‫مــن الواقــف منــذ أكثــر مــن خمســة عشــر عامـ ًا وكانــت اآلجــرة مائــة‬\n      ‫ألــف ريــال ملــدة عشــر ســنوات انتهــت يف ‪1430/5/30‬هـ ثــم جددنا العقد‬\n      ‫ملــدة عشــر ســنني بدايــة مــن ‪1430/6/13‬ه ـ بأجــرة قدرهــا (‪)140.000‬‬\n      ‫ريــال وقــد دفــع املدعــى عليهــا قيمــة أجــرة الســنة األولــى والثانيــة ولــم‬\n      ‫يدفعــا أجــرة الثالثــة والســبب هــو أن املدعــى أصالــة حضــر وابلــغ املدعــى‬\n      ‫عليهمــا أن والــده توفــى وطلــب األجــرة فطلــب املدعــى عليهمــا وكالــة‬\n      ‫مــن الورثــة أو صــك نظــارة ولــم يحضــر املدعــى ذلــك‪ ،‬وتقــدم بدعــواه‬\n      ‫مباشــرة واملدعــى عليهمــا مســتعدان بدفــع كامــل األجــرة وال يوجــد أي‬\n      ‫أضــرار باملبنــى وفق ـ ًا ملــا ذكــره املدعــى عليهمــا‪ .‬وبذلــك طلــب صــرف‬\n      ‫النظــر عــن الدعــوى‪ ،‬طلــب املدعــى عليــه البينــة فقــدم عقــد اإليجــار‬\n      ‫املــؤرخ ‪1430/6/6‬ه ـ ومضمونــة تأجيــر العقــار الســتخدامه مدرســة‬\n      ‫أهليــة بإيجــار ســنوي يدفــع علــى قســطني ومــدة اإليجــار عشــر ســنوات‬\n      ‫يجــدد دون شــرط أو قيــد أقــر املدعــي بصحــة العقــد ‪ ،‬قــدم املدعــى‬\n      ‫عليــه العقــود التــي اســتأجر بهــا العقــار منــذ عــام ‪1422‬ه ـ حتــى ‪1430‬ه ـ‬\n      ‫وجميعهــا مذيلــه بتوقيــع املؤجــر واملســتأجر‪ .‬واقــر املدعــى بصحــة العقود‬\n      ‫والتوقيــع عليهــا لوالــده‪ .‬وبســؤال املدعــى عليــه عــن التغيــرات يف ا ملبنــى‬\n      ‫فأجــاب أنهــا منــذ اســتأجر املبنــى واملبنــى املجــاور واململــوك لعــم املدعــى‬\n\n\n‫‪251‬‬\n\f                                          ‫نظــارة والناظــر كان علــى علــم بــه‪.‬‬\n‫وقــد قــدم املدعــى عليهمــا وكالــة كتــاب مطبوع ـ ًا للمؤجــر يفيــد‬\n‫زيــادة األجــرة مــن ‪1430/7/1‬ه ـ حتــى ‪1431/6/30‬ه ـ إلــى مائــة‬\n‫وأربعــن ألــف ريــال‪ .‬أنكــر املدعــى هــذه الورقــة وطلــب إحالتهــا‬\n‫إلــى األدلــة اجلنائيــة بشــرطة مكــة املكرمــة إلثبــات التالعــب فيهــا‬\n‫بالتزويــر والتزييف‪،‬ولقــد مت إحالــة األمــر للجهــة احملــددة بعــد موافقــة‬\n‫املدعــى عليــه‪ ،‬وورود اإلفــادة أنــه تعــذر إبــداء الــرأي الفنــي يف إثبــات‬\n‫أو نفــي التوقيــع بالســؤال الطرفــن عــن اإلضافــة أقــر املدعــى عليهمــا‬\n‫باســتعدادهما علــى دفــع كافــة األجــرة املســتحقة ملــدة ســنتني والشــيك‬\n‫ـاء علــى‬\n        ‫جاهــز‪ .‬أمــا املدعــى فقصــر طلباتــه علــى األجــرة واألخــاء ‪ -‬بنـ ً‬\n‫مــا تقــدم وبعــد االطــاع علــى عقــود التأجيــر بــن الطرفــن وقــد صــادق‬\n‫املدعــى نظــارة علــى هــذه العقــود جميعهــا‪ ،‬وأن والــده الواقــف هــو الــذي‬\n‫قــام بالتعاقــد والتوقيــع عليهــا وألن املؤجــر هــو املوقــف نفســه والن‬\n‫اإلجــارة عقــد الزم وال يبطــل بوفــاة املؤجــر ولــو كان ناظــر وقــف ألنــه‬\n‫أجــرة بصفتــه الناظــر علــى وقفــه وهــو قــد اشــترط النظــارة لنفســه‪،‬‬\n‫وألن الطرفــن تصادقــا علــى اســتالم أجــرة ‪1430‬ه ـ ‪1431 ،‬ه ـ لــذا‬\n‫فقــد ثبــت أن هــذا العقــد بــن الطرفــن هــو ملــدة عشــر ســنوات تبــدأ مــن‬\n‫‪1430/6/13‬ه ـ حتــى ‪1439/6/12‬ه ـ وأن األجــرة الســنوية ‪140.000‬‬\n‫ريــال لذلــك كلــه صــرف النظــر عــن طلــب املدعــى نظــاره باإلخــاء‬\n‫حــا ًال وطلبــه زيــادة األجــرة وإلــزام املدعــى عليــه أصالــة دفــع أجــرة عــام‬\n‫‪1432‬ه ـ وعــام ‪1433‬ه ـ مائتــن وثمانــن ألــف ريــال ودفــع أجــرة كل‬\n‫ســنة مــن الســنوات املتبقيــة وأن يخلــي العقــار يف نهايــة العقــد ســليم ًا‬\n‫خالي ـ ًا مــن الشــواغل بعــد إصــاح مــا قــام بــه مــن تعديــات‪ .‬وبعــرض‬\n\n\n                                                                                        ‫‪252‬‬\n\f      ‫احلكــم قــرر املدعــى عليــه وكالــة القناعــة وقــرر املدعــى وكالــة عــدم‬\n                        ‫القناعــة وصــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي انــا (‪ ).....‬القاضــي يف احملكمــة‬\n      ‫العامــة مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n      ‫رئيــس احملكمــة العامــة مبكــة املكرمــة برقــم ‪ 3347601‬وتاريــخ‬\n      ‫‪1433/1/18‬ه ـ املقيــدة باحملكمــة برقــم ‪ 33123046‬وتاريــخ‬\n      ‫‪1433/1/18‬ه ـ حضــر بالســجل املدنــي رقــم بوكالتــه عــن الناظــر على‬\n      ‫وقــف والــده مبوجــب صــك النظــارة الصــادر مــن هــذه احملكمــة برقــم‬\n      ‫‪ 32187615‬يف ‪1432/8/2‬ه ـ وذلــك بالوكالــة الصــادرة مــن كتابــة‬\n      ‫العــدل الثانيــة مبكــة برقــم ‪ 4949/25237‬يف ‪1432/8/18‬ه ـ والتــي‬\n      ‫تخولــه إقامــة وســماع الدعــاوى واملرافعــة واملدافعــة ‪...‬الــخ وادعــى علــى‬\n      ‫احلاضــر معــه بالســجل املدنــي رقــم بوكالتــه عــن بالســجل املدنــي رقــم‬\n      ‫بالســجل املدنــي رقــم بصفتهمــا الشــريكني بشــركة (‪ ).....‬وذلــك‬\n      ‫بالوكالــة الصــادرة مــن كتابــة العــدل الثانيــة مبكــة املكرمــة برقــم‬\n      ‫‪ 4596/23650‬يف ‪1431/7/23‬ه ـ والتــي تخولــه إقامــة وســماع عمــوم‬\n      ‫الدعــاوي واملرافعــة واملدافعــة ‪ ...‬الــخ قائــا يف دعــواه إن موكلــي هــو‬\n      ‫الناظــر علــى وقــف والــده اجلــاري حتــت نظــار موكلــي كامــل العقــار‬\n      ‫أرضــا وبنــاء الواقــع (‪ ).....‬والثابتــة وقفيتــه مبوجــب الصــك الصــادر مــن‬\n      ‫احملكمــة الكبــرى مبكــة برقــم ‪ 7/109‬يف ‪1411/3/4‬ه ـ وقــد أجــر‬\n      ‫الواقــف قبــل وفاتــه هــذا العقــار علــى املدعــى عليهمــا أصالــة ملــدة ســنة‬\n      ‫واحــدة ابتــداء مــن ‪1431/6/13‬ه ـ حتــى ‪1432/6/12‬ه ـ بأجــرة ســنوية‬\n\n‫‪253‬‬\n\f‫مائــة وأربعــن ألــف ريــال ولــم يدفعــا هــذه األجــرة حتــى اآلن وقــد انتهــت‬\n‫املــدة ولــم يخليــا العقــار حتــى اآلن كمــا أنهمــا أحدثــا أضــرار جذريــة‬\n‫باملبنــى أيضــا بتغييــر معاملــه وأبعــاده بإزالــة اجلــدار الفاصــل وإحــداث‬\n‫فتحــة مــن اجلنــب للطابــق العلــوي وإدخالــه علــى مبنــى الغيــر مخالفــة‬\n‫بذلــك البنــد الســادس مــن العقــد الــذي ينــص علــى (ال يجــوز للمســتأجر‬\n‫أحــداث شــيء يف العقــار أو تبديــل معاملــه أال مبوافقــة املؤجــر خطيــا‬\n‫وأال يكــون مســئوال عمــا يحدثــه أو يغيــره وللمؤجــر يف هــذه احلالــة‬\n‫احلــق مبطالبــة املســتأجر أعــادة املأجــور إلــى حالــه الســابق) والبنــد‬\n‫العاشــر (يف حالــة وقــوع تغييــر مــن املســتأجر وان أي مخالفــة أو ضــرر‬\n‫معناهمــا فســخ العقــد حــاال وااللــزم بــكل مــا يترتــب علــى ذلــك) وقــد‬\n‫مت إخطــار املدعــى عليهمــا خطيــا قبلهــا بشــهر املوجــب البنــد التاســع‬\n‫بالعقــد‪ ،‬بضــرورة اإلخــاء بعــد إصــاح وإعــادة مــأمت تغييــره يف املبنــي‬\n‫إلــى ســابقة ‪ ،‬وبزيــادة األجــرة الســنوية لعــام ‪1433‬ه ـ إلــى مبلــغ وقــدره‬\n‫(‪)250,000‬مائتــان وخمســون ألــف ريــال ‪،‬كزيــادة مبوجــب عــدم القيــد‬\n‫يف األجــرة عنــد جتديــد العقــد ســنويا ‪،‬كمــا أنهمــا مياطــان ويتهربــان‬\n‫مــن ســداد مــا اســتحق بذمتهمــا مــن دفــع األجــرة املتأخــرة واحلالــة‬\n‫عليهمــا ويصــران علــى عــدم االلتــزام بشــي إلــى حــد عــدم التجــاوب‬\n‫فأطلــب مــن فضيلتكــم‪ -1 :‬إلــزام املدعــى عليهــا بدفــع األجــرة املترتبــة‬\n‫بذمتهــا واملتأخــرة بتاريــخ ‪1431/6/13:‬ه ـ إلــى ‪1432/12/12‬ه ـ مبلــغ‬\n‫وقــدره (‪)70,000‬ســبعون ألــف ريــال‪ -2 .‬إلــزام املدعــى عليهمــا بدفــع‬\n‫األجــرة احلالــة بتاريخ‪1432/12/13:‬ه ـ إلــى ‪1433/6/12‬ه ـ مبلغ وقدره‬\n‫(‪ )125,000‬مبوجــب الزيــادة احلاصلــة يف األجــرة بخطــاب اإلخطــار‬\n‫املســتلم مــن قبــل املدعــى عليهمــا ‪،‬كمــا نصــت عليــه بنــود العقــد‬\n\n\n                                                                                     ‫‪254‬‬\n\f                                                             ‫العاشــر واحلــادي عشــر‪.‬‬\n      ‫‪ -3‬انتــداب جلنــة اخلبــراء للخــروج والوقــوف علــى املبنــى ومعاينــة اإلضــرار‬\n      ‫والتغييــرات التــي أحدثتهــا املدعــى عليهمــا وإلزامهمــا بتحمــل نفقــات‬\n      ‫اإلصالحــات عينــا أو نقــد عــن طريــق الكتابــة للجنــة اخلبــراء بإحالتهــا‬\n      ‫ملكتــب أشــراف هندســي إلعــادة مــأمت إزالتــه لوضعــه الســابق مبوجــب‬\n      ‫احلــدود املثبتــة بصــك مبنــى الوقــف مــع اإلخــاء يف نهايــة الفتــرة‬\n      ‫بتاريخ‪1433/6/12:‬ه ـ ‪ -4‬إلــزام املدعــى عليهمــا دفع أتعاب ومصاريف‬\n      ‫احملامــاة مبلــغ وقــدره (‪ )50,000‬ريــال هــذه دعــواي وبســؤال املدعــى‬\n      ‫عليــه وكالــة عــن دعــوى املدعــي وكالــة أجــاب قائــا إن موكلــي‬\n      ‫اســتأجرا هــذا العقــار أرضــا وبنــاء مــن الواقــف منــذ أكثــر مــن خمســة‬\n      ‫عشــر عامــا وكانــت األجــرة مائــة ألــف ريــال وكان لنــا عقــد معــه ســابق‬\n      ‫ملــدة عشــر ســنني بــدأت يف ‪1421/6/1‬ه ـ وانتهــت يف ‪1430/5/30‬ه ـ ثم‬\n      ‫جددنــا العقــد معــه ملــدة عشــر ســنني ابتــداء مــن ‪1430/6/13‬ه ـ بأجــرة‬\n      ‫ســنوية مائــة وأربعــن ألــف ريــال وقــد دفــع موكلــي أجــرة الســنة األولــى‬\n      ‫مــن العقــد اجلديــد التــي بــدأت يف ‪1430/6/13‬ه ـ كمــا دفعــا أجــرة‬\n      ‫الســنة الثانيــة التــي بــدأت يف ‪1431/6/13‬ه ـ ولــم يدفعــا أجــرة الســنة‬\n      ‫الثالثــة التــي بــدأت يف ‪1432/6/13‬ه ـ وســبب ذلــك أن املدعــي أصالــة‬\n      ‫حضــر ملوكلــي وأبلغهمــا أن والــده تــويف وطلــب األجــرة فطلــب منــه‬\n      ‫مــوكالي وكالــة مــن الورثــة إن كان العقــار إرثــا أو صــك نظــارة ولــم‬\n      ‫يحضــر لنــا ذلــك وتقــدم بهــذه الدعــوى مباشــرة ومــوكالي مســتعدان‬\n      ‫بدفــع كامــل األجــرة مائــة وأربعــن ألــف ريــال أمــا مــا ذكــره مــن‬\n      ‫أحــداث أضــرار يف العقــار فهــذا ال صحــة لــه فــا يوجــد أي أضــرار‬\n      ‫أحلقهــا مــوكالي بالعقــار وإمنــا مــوكالي مســتأجرين لهــذا املبنــى‬\n\n\n‫‪255‬‬\n\f‫ومبنــى مجــاور لــه اململــوك لعــم املدعــي نظــارة وهمــا يســتخدمان املبنيــن‬\n‫مدرســة وقامــا بهــدم اجلــدار الفاصــل بينهمــا كمــا قامــا بعمــل جســر‬\n‫علــوي لوصــل املبنيــن معــا حلاجــة املدرســة لذلــك ومتــى انتهــت مــدة‬\n‫العشــر ســنني أي يف ‪1440/6/12‬ه ـ ســيقوم موكلــي بإصــاح جميــع ما‬\n‫أحدثــاه يف العقــار وإعادتــه كمــا كان ســابقا وأمــا رفــع األجــرة فــا‬\n‫حــق للمدعــي أصالــة فيــه ألن العقــد موقــع مــع الواقــف ملــدة عشــر ســنني‬\n‫بأجــرة مائــة وأربعــن ألــف ريــال وال نوافــق علــى دفــع أتعــاب احملامــاة ألن‬\n‫املدعــي نظــارة لــو أبــرز لنــا صــك النظــارة لســلمناه األجــرة مباشــرة‬\n‫وأطلــب صــرف النظــر عــن هــذه الدعــوى وبعــرض ذلــك علــى املدعــي‬\n‫وكالــة قــال األجــرة ملــدة ســنة واحــدة بــدأت يف ‪1431/6/13‬ه ـ وانتهــت‬\n‫يف ‪1432/6/12‬ه ـ وليســت كمــا ذكــر املدعــى عليــه وكالــة عشــر‬\n‫ســنني وصحيــح أن موكلــي ووالــده مــن قبــل يعلمــان بجميــع التغييــرات‬\n‫التــي قــام بهــا املســتأجران يف العقــار وأنهمــا يســتخدمان العقــار مدرســة‬\n‫وأن العقــار املجــاور لهــذا العقــار والــذي يســتأجره املدعــى عليهمــا هــو‬\n‫لعــم موكلــي ولكــن هــذا بــدون إذن خطــي مــن الواقــف أو الناظــر‬\n‫احلالــي وســبب تقــدم موكلــي بهــذه الدعــوى هــو أنــه ذهــب إليهــم وطلــب‬\n‫منهــم دفــع األجــرة فرفــض املدعــى عليهمــا أصالــة بــدون ســبب هكــذا‬\n‫قــرر فطلبــت مــن املدعــي صــك النظــارة وصــك امللكيــة للعقــار وعقــد‬\n‫اإليجــار فأبــرز صــك الوقفيــة الصــادر مــن هــذه احملكمة برقــم ‪7/109‬‬\n‫يف ‪1411/3/4‬ه ـ وباالطــاع عليــه وجدتــه يتضمــن ثبــوت للمحــدود‬\n‫الــذي ميلكــه مبوجــب الصــك الصــادر مــن كتابــة العــدل برقــم ‪ 271‬يف‬\n‫‪1392/2/1‬ه ـ الواقــع بالرصيفــة واحملــدود واملــذروع باطنــه علــى اجلهات‬\n‫املشــروطة املوضحــة باطنــه ا‪.‬ه ـ كمــا أبــرز صــك النظــارة الصــادر مــن‬\n\n\n                                                                                      ‫‪256‬‬\n\f      ‫هــذه احملكمــة برقــم ‪ 32187615‬يف ‪1432/8/2‬ه ـ وباالطــاع عليــه‬\n      ‫وجدتــه يتضمــن إقامــة ناظــرا علــى وقــف والــده الثابــت مبوجــب صــك‬\n      ‫الوقفيــة الصــادر مــن هــذه احملكمــة برقــم ‪ 7/109‬يف ‪1411/3/4‬ه ـ‬\n      ‫وألن املدعــى عليــه وكالــة دفــع بــأن موكليــه مســتأجران للعقــار ملــدة‬\n      ‫عشــر ســنني بــدأ مــن ‪1430/6/13‬ه ـ لــذا فقــد طلبــت منــه البينــة علــى‬\n      ‫ذلــك فقــال لــدي عقــد اإليجــار املــؤرخ يف ‪1430/6/6‬ه ـ وباالطــاع عليــه‬\n      ‫وجدتــه يتضمــن تأجيــر الطــرف األول عمارتــه املكونــة مــن أربعــة أدوار‬\n      ‫علــى الطــرف الثانــي مدرســة (‪ ).....‬الســتخدامها مدرســة أهليــة بإيجــار‬\n      ‫ســنوي مائــة وأربعــن ألــف ريــال تدفــع علــى قســطني القســط األول يف‬\n      ‫الفصــل الدراســي األول والقســط الثانــي يف الفصــل الدراســي الثانــي‬\n      ‫ومــدة اإليجــار عشــر ســنوات ويجــدد دون شــرط أو قيــد تبــدأ مــن‬\n      ‫‪1430/6/13‬ه ـ وتنتهــي يف ‪1431/6/2‬ه ـ ثــم شــروط العقــد ثــم توقيــع‬\n      ‫شــاهدين وتوقيــع الطــرف األول املؤجــر وتوقيع الطرف الثاني املســتأجر‬\n      ‫وختــم مــدارس (‪ ).....‬أه ـ وبعــرض هــذا العقــد علــى املدعــي نظــارة قــال‬\n      ‫هــذا العقــد صحيــح وأن مــدة اإليجــار عشــر ســنني ولكــن هــذه املــدة‬\n      ‫للتجديــد فقــط باتفــاق الطرفــن يف كل ســنة مــن هــذه الســنني العشــر‬\n      ‫بدليــل أن العقــد قــد ثبــت فيــه أن املــدة تبــدأ يف ‪1430/6/13‬ه ـ وتنتهــي‬\n      ‫يف ‪1431/6/2‬ه ـ والتوقيــع علــى هــذا العقــد هــو توقيــع والــدي املوقــف‬\n      ‫هكــذا قــرر وبعــرض ذلــك علــى املدعــي عليــه وكالــة قــال العقــد عشــر‬\n      ‫ســنني وكتابــة تاريــخ ســنه هــو مــن أجــل تقــدمي العقــد للجنــة إســكان‬\n      ‫احلجــاج ألنهــا ال تقبــل إال عقــد فيــه تاريــخ الســنة وأننــا بنــاء علــى ذلــك‬\n      ‫نقــوم يف كل ســنة بكتابــة عقــد مــؤرخ للســنة ومكتــوب فيــه أن العقــد‬\n      ‫ملــدة عشــر ســنني ولذلــك فــان والــد املدعــي نظــارة أيضــا كتــب لنــا‬\n\n\n‫‪257‬‬\n\f‫عقــدا للســنة الثانيــة مــن العشــر ســنني وقــد نــص فيــه أن العقــد ملــدة‬\n‫عشــر ســنني ويجــدد دون شــرط أو قيــد يبــدأ يف ‪1431/6/13‬ه ـ حتــى‬\n‫‪1432/6/12‬ه ـ كمــا أن املالــك الســابق للمدرســة كان يعمــل ذلــك مــع‬\n‫والدهــم ونحــن اســتلمنا املبنــى منــه وكان يكتب عقدا ســنويا مذكور‬\n‫يف كل عقــد أن العقــد ملــدة عشــر ســنني هكــذا قــرر فطلبــت منــه‬\n‫العقــود التــي يذكرهــا فأبــرز عقــدا مؤرخــا يف ‪1431/6/29‬ه ـ‬\n‫وباالطــاع عليــه وجدتــه يتضمــن تأجيــر الطــرف األول املؤجــر علــى‬\n‫الطــرف الثانــي مــدارس (‪ ).....‬العمــارة املكونــة مــن أربعــة أدوار‬\n‫الســتخدامها مدرســة أهليــة بأجــرة مائــة وأربعــن ألــف ريــال تدفــع علــى‬\n‫قســطني القســط األول يف الفصــل الدراســي األول والقســط الثانــي يف‬\n‫الفصــل الدراســي الثانــي ومــدة اإليجــار عشــر ســنني تبــدأ مــن‬\n‫‪1431/6/13‬ه ـ وتنتهــي يف ‪1432/6/12‬ه ـ ثــم شــروط العقــد وتوقيــع‬\n‫الطرفــن كمــا أبــرز خمســة عقــود جميعهــا تتضمــن تأجيــر الطــرف‬\n‫األول الطــرف الثانــي العمــارة املكونــة مــن أربعــة ادوار الســتعمالها‬\n‫مدرســة بأجــرة ســنوية مائــة ألــف ريــال تدفــع علــى قســطني القســط‬\n‫األول يف الفصــل الدراســي األول والقســط الثانــي يف الفصــل الدراســي‬\n‫الثانــي ومــدة اإليجــار عشــر ســنوات ثــم ذكــر يف العقــد األول انــه تبــدأ‬\n‫مــن ‪1422/6/1‬ه ـ وتنتهــي يف ‪1423/5/30‬ه ـ والعقــد الثانــي يبــدأ يف‬\n‫‪1422/6/13‬ه ـ وينتهــي يف ‪1423/6/29‬ه ـ والعقــد الثالــث يبــدأ مــن‬\n‫‪1423/6/13‬ه ـ وينتهــي يف ‪1424/6/13‬ه ـ والعقــد الرابــع يبــدأ مــن‬\n‫‪1425/6/13‬ه ـ وينتهــي يف ‪1426/6/12‬ه ـ والعقــد اخلامــس يبــدأ مــن‬\n‫‪1426/6/13‬ه ـ وينتهــي يف ‪1427/6/12‬ه ـ وجميعهــا مذيلــة بتوقيــع‬\n‫املؤجــر واملســتأجر كمــا أبــرز املدعــى عليــه وكالــة ثالثــة عقــود‬\n\n\n                                                                                   ‫‪258‬‬\n\f      ‫وتتضمــن جميعهــا أن الطــرف األول الطــرف الثانــي مــدارس (‪).....‬‬\n      ‫العمــارة املكونــة مــن أربعــة أدوار الســتعمالها مدرســة أهليــة بأجــرة‬\n      ‫ســنوية مائــة ألــف ريــال تدفــع علــى قســطني القســط األول يف الفصــل‬\n      ‫الدراســي األول والقســط الثانــي يف الفصــل الدراســي الثانــي ومــدة‬\n      ‫اإليجــار عشــر ســنني ثــم كل عقــد منهــا لــه تاريــخ بدايــة ونهايــة فالعقــد‬\n      ‫األول يبــدأ يف ‪1427/6/13‬ه ـ وينتهــي يف ‪1428/6/12‬هـ والعقد الثاني‬\n      ‫يبــدأ يف ‪1428/6/13‬ه ـ وينتهــي يف ‪1429/6/12‬ه ـ والعقــد الثالــث‬\n      ‫يبــدأ يف ‪1429/6/13‬ه ـ وينتهــي يف ‪1430/6/12‬ه ـ وجميعهــا مذيلــة‬\n      ‫بتوقيــع املؤجــر واملســتأجر وقــرر املدعــى عليــه وكالــة إن جميــع هــذه‬\n      ‫العقــود هــي ملــدة واحــدة عشــر ســنني بــدأ يف عــام ‪1420‬ه ـ وانتهــت يف‬\n      ‫عــام ‪1430‬ه ـ وكل ســنة مبائــة ألــف ريــال وملــا انتهــت العشــر ســنني‬\n      ‫طالــب املؤجــر بزيــادة األجــرة فوافــق موكلــي علــى الزيــادة ومت االتفــاق‬\n      ‫علــى أن تكــون األجــرة مائــة وأربعــن ألــف ريــال ســنويا وان مــدة العقــد‬\n      ‫عشــر ســنني وهــذا يثبــت أن مــدة اإليجــار عشــر ســنني هكــذا قــرر‬\n      ‫وبعــرض هــذه العقــود علــى املدعــي نظــارة قــال العقود صحيحــة والتوقيع‬\n      ‫عليهــا هــو توقيــع والــدي املوقــف ولكــن ذكــر مــدة العقــد عشــر ســنني‬\n      ‫ال يعنــي أن هــذه املــدة هــي مــدة اإليجــار وإمنــا تكــون يف حــال االتفــاق‬\n      ‫بــن الطرفــن يف كل ســنة مســتقلة هكــذا قــرر وجــرى ســؤال املدعــى‬\n      ‫عليــه وكالــة عــن هــذه التغيــرات يف املبنــى هــل هــي جديــدة أم قدميــة‬\n      ‫فقــال إنهــا قدميــة منــذ اســتأجرنا املبنــى واملبنــى املجــاور لــه اململــوك لعــم‬\n      ‫املدعــي نظــارة وكان الواقــف علــى علــم بــه اطــاع منــذ عملنــا وحتــى‬\n      ‫وفاتــه ولــم يعتــرض علــى ذلــك هكــذا قــرر وبعــرض ذلــك علــى املدعــي‬\n      ‫وكالــة قــال صحيــح إن هــذه التعديــات منــذ حوالــي ثمانيــة ســنني‬\n\n\n‫‪259‬‬\n\f‫وكان الواقــف علــى علــم بهــا منــذ القيــام بهــا ولكــن لــم يعطيهــم أذن‬\n‫خطيــا بذلــك هكــذا قــرر ثــم قــرر املدعــى عليــه وكالــة قائــا إن لــدي‬\n‫زيــادة بينــة وأبــرز كتابــا مطبوعــا مــن املؤجــر وهــذا نصــه ‪ -:‬الســام‬\n‫عليكــم ورحمــة اهلل وبركاتــه ‪ ،‬وبعــد ‪ -:‬أحيــط علــم ســعادتكم بــأن‬\n‫عقــد اإليجــار املبــرم بيننــا اخلــاص باملدرســة ســينتهي بتاريــخ‬\n‫‪1430/6/30‬ه ـ لــذا أود لفــت انتباهكــم أنــه ســيكون اإليجــار اجلديــد‬\n‫إن أردمت التجديــد مبلــغ وقــدره ( ‪ ) 150.000‬فقــط مائــة وخمســون ألــف‬\n‫ريــال للعــام الواحــد ‪ ،‬والــذي تكــون بدايتــه ‪1430/7/1‬ه ـ ‪ .‬وينتهــي يف‬\n‫‪1431/6/30‬ه ـ باإلضافــة إلــى املتفــق عليــه يف ملحــق العقــد الســابق ‪،‬‬\n‫وإن لــم تكــن هنــاك موافقــة نأمــل منكــم إعــادة بويــة األبــواب وكل مــا‬\n‫تغيــر باملبنــى إلــى مــا كان عليــه عنــد اســتالمكم املبنــى حتــى يتســنى‬\n‫لنــا اســتالمه وإذا لــم تكــن الرغبــة يف التجديــد عليكــم إبالغنا كتابة‬\n‫وتســليم املبنــى يف نهايــة العقــد‪ ،‬وإذا لــم يســلم املبنــى فتكــون إيجــاره‬\n‫كمــا ذكــرت ( ‪ ) 150.000‬ألــف ريــال ســنويا حتــى ولــو كان يومــا‬\n‫واحــدا بعــد انتهــاء العقــد املؤجــر توقيــع ا‪.‬ه ـ ‪،‬ثــم أضــف بخــط اليــد مــا‬\n‫نصــه ‪ -:‬اتفــق علــى اإليجــار اجلديــد (‪ )140.000‬ألــف ريــال مائة وأربعون‬\n‫ألــف ريــال ســنويا تدفــع علــى قســطني ابتــداء مــن عــام ‪1430/6/13‬ه ـ‬\n‫حتــى ‪1439/6/12‬ه ـ ا‪.‬ه ـ وبعــرض هــذه الورقــة علــى املدعــي وكالــة‬\n‫قــال إن موكلــي أفــاد بــأن والــده لــم يكــن يعلــم بهــذه التعديــات‬\n‫وبســؤال املدعــي وكالــة عــن الورقــة التــي أبرزهــا املدعــى عليــه وكالــة‬\n‫يف اجللســة املاضيــة فأبــرز ردا هــذا نصــه ‪ -:‬نتقــدم لفضيلتكــم بــرد‬\n‫علــى اخلطــاب املقــدم مــن املدعــى عليهمــا وكالــة يف اجللســة الســابقة ‪،‬‬\n‫وحيــث إنــه بالرجــوع إلــى موكلــي أتضــح لــه أن التوقيــع املشــار إليــه يف‬\n\n\n                                                                                      ‫‪260‬‬\n\f      ‫اخلطــاب يختلــف عــن توقيــع والــده الشــيخ‪ ، ...........‬ولــذا فإننــا نطلــب‬\n      ‫إحالتهــا لألدلــة اجلنائيــة للكشــف عنهــا ومطابقتهــا مــع تواقيــع مــورث‬\n      ‫موكلــي‪ ،‬حيــث إن جميــع مــا جــاء يف الورقــة غيــر صحيــح وينقــض‬\n      ‫بعضــه بعضــا مــن تضــارب لألقــوال باملجلــس الشــرعي للمدعــى عليهمــا‬\n      ‫وبــن مــا تقدمــت بــه بالباطــل ‪ ،‬فقــد جــاء يف النــص املكتــوب بواســطة‬\n      ‫احلاســب يف الورقــة مــا يثبــت صحــة أدعــاء موكلــي بــان األجــرة ســنوية‬\n      ‫تبــدأ مــن عــام ‪1430‬ه ـ وتنتهــي عــام ‪1431‬ه ـ ‪ ،‬ومت وضــع الزيــادة عليهــا‬\n      ‫مــن قبــل املدعــى عليهــا بخــط اليــد الــذي ال ميثــل خطــا لوالــد موكلــي‬\n      ‫رحمــة اهلل تزويــرا بــان األجــرة تبــدأ مــن عــام ‪1430‬هـ إلــى ‪1439‬هـ كما‬\n      ‫أن التوقيــع ليــس توقيــع املؤجــر رحمــة اهلل بــل لفــق وزور عليــه ‪ ،‬علمــا أن‬\n      ‫املؤجــر كان يســتطيع الكتابــة والتوقيــع حلــن وقــت وفاتــه وقــد أقــر‬\n      ‫املدعــى عليــه وكالــة أكثــر مــن مــرة لــدى فضيلتكــم بــان األجــرة‬\n      ‫ســنوية وباتفــاق الطرفــن وإقــراره هــذا يعــد حجــة قاصــرة عليــه يؤخــذ‬\n      ‫بهــا ‪ ،‬ولــذا نلتمــس لفضيلتكــم إحالــة الورقــة املقدمــة إلــى األدلــة‬\n      ‫اجلنائيــة بشــرطة مكــة املكرمــة إلثبــات التالعــب فيهــا بالتزويــر‬\n      ‫والتزييــف ا‪.‬ه ـ وبعــرض ذلــك علــى املدعــى عليــه وكالة قــال إن الكتابة‬\n      ‫التــي بخــط اليــد ليســت كتابــة الواقــف ألنهــا كتابــة احملاســب لدينــا‬\n      ‫وأنــا موافــق علــى طلــب املدعــي وكالــة إحالــة الورقــة للجهــة املختصــة‬\n      ‫لإلفــادة علــى التزويــر مــن عدمــه هكــذا قــرر ولــذا فقــد جــرت الكتابــة‬\n      ‫للجهــة املختصــة لإلفــادة عــن تزويــر التوقيــع املذيــل بهــذه الورقــة مــن‬\n      ‫عدمهــا وذلــك بخطابــي رقــم ‪ 331219100‬يف ‪1433/6/29‬ه ـ فــوردت‬\n      ‫االفــاده مــن مديــر قســم أمــن احملكمة برقــم ‪/849‬ع يف ‪1433/9/10‬هـ‬\n      ‫علــى خطــاب مديــر شــعبة التحريــات والبحــث اجلنائــي برقــم ‪ 527807‬يف‬\n\n\n‫‪261‬‬\n\f‫‪1433/9/6‬ه ـ وبرفقــه التقريــر الفنــي إلدارة الفحــوص الفنيــة للتزييــف‬\n‫والتزويــر شــعبة فحــص اخلطــوط والتواقيــع برقــم ‪ 33561‬وهــذا نــص‬\n‫الفحــص والنتيجــة بدراســة التوقيــع املنســوب للمتوفــى (‪ ).....‬والثابــت‬\n‫بورقــة االتفــاق علــى عقــد اإليجــار ( موضــوع الفحــص ) وجدنــا أنــه‬\n‫عبــارة عــن تكويــن بســيط ال يحمــل املميــزات واخلصائــص اخلطيــة لليــد‬\n‫الكاتبــة لــذا يتعــذر إبــداء الــرأي الفنــي يف إثبــات أو نفــي التوقيــع عــن‬\n‫يــد املذكــور أه ـ وبعــرض ذلــك علــى الطرفــن قــال املدعــي وكالــة إن‬\n‫هــذا يــدل علــى عــدم صحــة هــذه الورقــة وأن التوقيــع املذيــل بهــا ليــس‬\n‫توقيــع والــدي هكــذا قــرر وقــال املدعــى عليــه إننــا قدمنــا عشــرة عقــود‬\n‫أصالــة للجهــة الفاحصــة موقــع عليهــا مــن قبــل والــد الناظــر وال أعلــم‬\n‫ملــاذا اعتــذرت اجلهــة الفاحصــة عــن إبــداء الــرأي هكــذا قــرر وبســؤال‬\n‫الطرفــن هــل لديهمــا مــا يضيفانــه يف هــذه القضيــة قــال املدعــي وكالــة‬\n‫إننــي أطلــب األجــرة مــن تاريــخ ‪1432/6/13‬ه ـ حتــى ‪1434/6/12‬ه ـ أي‬\n‫مــدة ســنتني وأجــرة العــام مائــة وأربعــون ألــف ريــال ومجمــوع األجــرة‬\n‫املتبقيــة هــي مبلــغ وقــدره مائتــان وثمانــون ألــف ريــال وإخــاء املوقــع يف‬\n‫‪1434/6/12‬ه ـ مــع إصــاح جميــع التعديــات التــي قــام بهــا املدعــى‬\n‫عليــه بإرجــاع اجلــدار الفاصــل وســد الفتحــة املوجــودة يف الطابــق العلــوي‬\n‫وإعــادة األبــواب ألماكنهــا هكــذا قــرر وبعــرض ذلــك علــى املدعــى‬\n‫عليــه وكالــة قــال إن موكلــي مســتعد بدفــع كامــل املبالــغ املتبقيــة‬\n‫بذمتــه وأطلــب إمهالــي ملراجعــة مقــدار املبلــغ املتبقــي وأمــا اإلخــاء فــا‬\n‫نوافــق عليــه وموكلــي ليــس لديــه مــا يضيفــه يف هــذه القضيــة كمــا‬\n‫جــرى ســؤال املدعــى عليــه وكالــة عــن املبلــغ املتبقــي حتــى اآلن فقــال إن‬\n‫موكلــي مقــر بأنــه للمدعــي نظــارة كامــل أجــرة ســنتني بــدأت يف‬\n\n\n                                                                                     ‫‪262‬‬\n\f      ‫‪1432/6/13‬ه ـ حتــى ‪1434/6/12‬ه ـ مبلــغ وقــدره مائتــان وثمانون ألف‬\n      ‫ريــال وموكلــي لــم ميتنــع مــن دفــع املبلــغ والشــيك جاهــز وموكلــي‬\n      ‫مســتعد بدفعــه حــاال ولكــن املدعــي نظــارة لــم يحضــر الســتالمه‬\n      ‫هكــذا قــرر وبســؤال الطرفــن هــل لديهمــا مــا يضيفانــه يف هــذه‬\n      ‫القضيــة فقــاال ليــس لدينــا ســوى مــا قدمنــاه ســلفا ثــم قــرر املدعــى عليــه‬\n      ‫أننــي أحضــرت أجــرة ســنتني ابتــداء مــن ‪1432/6/13‬ه ـ حتــى نهايــة‬\n      ‫‪1434/6/12‬ه ـ وأبــرز املدعــى عليــه وكالــة شــيكا مصرفيــا مســحوبا‬\n      ‫علــى البنــك (‪ ).....‬برقــم ‪ 44496‬يف ‪1434/2/13‬ه ـ ألمــر املدعــي نظــارة‬\n      ‫(‪ ).....‬مببلــغ مائتــن وثمانــن ألــف ريــال وطلــب تســليم هــذا الشــيك‬\n      ‫للمدعــي نظــارة وبعــرض ذلــك علــى املدعــي وكالــة قــال أطلــب إمهالــي‬\n      ‫ملراجعــة موكلــي ثــم جــرى اطالعــي علــى صــك حصــر الورثــة الصــادر‬\n      ‫مــن هــذه احملكمــة برقــم ‪ 3297791‬يف ‪1432/5/12‬ه ـ فوجدتــه‬\n      ‫يتضمــن ثبــوت وفــاة بتاريــخ ‪1432/3/1‬ه ـ وانحصــار إرثــه يف زوجتــه ويف‬\n      ‫أوالده منهــا ال وراث لــه ســواهم كمــا جــرى اطالعــي علــى صــك الوقفية‬\n      ‫الصــادر مــن هــذه احملكمــة برقــم ‪ 7/109‬يف ‪1411/3/4‬ه ـ فوجدتــه‬\n      ‫يتضمــن وقفيــة لكامــل العقــار أرضــا وبنــاء الواقــع (‪ ).....‬واحملــدودة‬\n      ‫واملذروعــة مبوجــب صــك التملــك الصــادر مــن كتابــة العــدل مبكــة‬\n      ‫برقــم ‪ 271‬يف ‪1399/2/1‬ه ـ علــى نفســه مــدة حياتــه ينتفــع بــه ســكنا‬\n      ‫وإســكانا وغلــة واســتغالال ثــم علــى ذريتــه ذكــورا وإناثــا بالفريضــة‬\n      ‫الشــرعية ثــم مــن بعدهــم علــى أوالدهــم وأوالد أوالدهــم كمــا اشــترط‬\n      ‫يف وقفــه هــذا أن تكــون النظــارة لنفســه مــدة حياتــه ثــم مــن بعده تكون‬\n      ‫النظــارة لألرشــد فاألرشــد مــن أبنائــه الذكــور أوال ثــم اإلنــاث أه ـ ثــم‬\n      ‫أبــرز املدعــي وكالــة ورقــة هــذا نصهــا ردا علــى مــا تقــدم يف اجللســة‬\n\n\n‫‪263‬‬\n\f‫الســابقة فعليــه نــود اســتالم مبلــغ األجــرة املتأخــرة عنــد انتهــاء ألقضيــة‬\n‫وذلــك بعــد ان امتنعــت املدعــى عليهــا عــن الدفــع ألكثــر مــن ســنتني‬\n‫كمــا نفيــد فضيلتكــم بــان دعونــا تنحصــر يف األجــرة واإلخــاء معــا‬\n‫وقــد مت إبــاغ املدعــى عليهــا مبوجــب خطــاب اســتلمته بإخــاء املبنــى‬\n‫بعــد إعادتــه إلــى حالتــه الســابقة بســد اخلــرم بالطابــق العلــوى وإعــادة‬\n‫اجلــدار الفاصــل بــن املبنيــن وإرجــاع جميــع األبــواب والنوافــذ للمبنــى‬\n‫كمــا كانــت ‪،‬وحــال تأخــرت او امتنعــت عــن اإلخــاء فســتكون‬\n‫هنــاك زيــادة يف أجــرة املبنــى مقدارهــا مائــة وعشــرة أالف ريــال ‪ ،‬وذلــك‬\n‫ألنتهــا العقــد وعــدم رغبتنــا بتأجيــر املدعــى عليهــا لســنه ايجاريــة أخــرى‬\n‫فنرجــو مــن فضيلتكــم إلــزام املدعــى عليهــا باإلخــاء وتســليم املبنــى‬\n‫كذلــك بعــد إعادتــه إلــى حالتــه الســابقة التــى كان عليهــا وبعــرض‬\n‫ذلــك علــى املدعــى عليــه وكالــة قــال إن موكلــي لــم ميتنعــا مــن دفــع‬\n‫أجــرة الســنتني الســابقتني ونحــن ملتزمــون بدفعهــا حــاال هكــذا قرر أهـ‬\n‫فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وبعــد االطــاع علــى صــك‬\n‫الوقفيــة والنظــارة وحصــر الورثــة وبعــد االطــاع علــى عقــود التأجيــر‬\n‫بــن الطرفــن والتــي كانــت ملــدة عشــر ســنني بــدأت يف ‪1421/6/1‬ه ـ‬\n‫وانتهــت يف ‪1430/6/12‬ه ـ ثــم عقــدي األجــرة األول بــدأ يف‬\n‫‪1430/6/13‬ه ـ والثانــي بــدأ يف ‪1431/6/13‬ه ـ واملنصــوص يف هذيــن‬\n‫العقديــن أن مــدة العقــد عشــر ســنني واألجــرة الســنوية مائــة وأربعــون‬\n‫ألــف ريــال وقــد صــادق املدعــي نظــارة علــى هــذه العقــود جميعــا وان‬\n‫والــده الواقــف هــو الــذي قــام بالتعاقــد والتوقيــع عليهــا وألن املؤجــر يف‬\n‫هذه العقود هو املوقف نفســه وقد اشــترط لنفســه االســتحقاق والنظارة‬\n‫مــدة حياتــه وألن اإلجــارة عقــد الزم وال يبطــل العقــد بوفــاة املؤجــر ولــو‬\n\n\n                                                                                      ‫‪264‬‬\n\f      ‫كان ناظــر وقــف ألنــه أجــرة بصفتــه الناظــر علــى وقفــه وهو قد اشــترط‬\n      ‫النظــارة لنفســه ينظــر منتهــى اإلرادات البــن النجــار ‪ 63/5‬وكشــاف‬\n      ‫القنــاع ‪ 75-74/9‬وألن الطرفــن تصادقــا علــى اســتالم أجــرة عامــي‬\n      ‫‪1430‬ه ـ ‪1431‬ه ـ وعلــى عــدم اســتالم املدعــي نظــارة أجــرة عامــي‬\n      ‫‪1432‬ه ـ ‪1433‬ه ـ لــذا فقــد ثبــت لــدي إن هــذا العقــد بــن الطرفــن هــو‬\n      ‫عقــد ملــدة عشــر ســنني بــدأت بتاريــخ ‪1430/6/13‬ه ـ وتنتهــي يف‬\n      ‫‪1439/6/12‬ه ـ وأن األجــرة الســنوية مائــة وأربعــن ألــف ريــال لذلــك‬\n      ‫كلــه فقــد صرفــت النظــر عــن طلــب املدعــي نظــارة اإلخــاء حــاال وطلبه‬\n      ‫زيــادة األجــرة وألزمــت املدعــى عليــه أصالــة بدفــع أجــرة عــام ‪1432‬ه ـ‬\n      ‫وعــام ‪1433‬ه ـ مائتــن وثمانــن ألــف ريــال وأن يدفــع أجــرة كل ســنة مــن‬\n      ‫الســنوات املتبقيــة حتــى انتهــاء العقــد كل قســط يف وقتــه احملــدد‬\n      ‫القســط األول يف بدايــة الفصــل الدراســي والقســط الثانــي يف بدايــة‬\n      ‫الفصــل الدراســي الثانــي وأن يخلــي املدعــى عليــه العقــار يف نهايــة العقــد‬\n      ‫ســليما خاليــا مــن الشــواغل بعــد إصــاح جميــع مــا قــام بــه مــن تعديــات‬\n      ‫وبذلــك كلــه حكمــت وبعــرض احلكــم علــى الطرفــن قــرر املدعــى‬\n      ‫عليــه وكالــة القناعــة وقــرر املدعــي وكالــة عــدم القناعــة وطلــب رفعــه‬\n      ‫حملكمــة االســتئناف بعــد تقــدمي الئحــة اعتراضيــة عليــه فأفهمتــه‬\n      ‫مبراجعــة احملكمــة خــال عشــرة أيــام الســتالم الصــك وتقــدمي الالئحــة‬\n      ‫االعتراضيــة خــال ثالثــن يومــا مــدة االعتــراض فــإذا تأخــر ســقط حقــه‬\n      ‫يف طلــب االســتئناف واكتســب احلكــم القطيعــة ثــم ســلم املدعــى عليــه‬\n      ‫وكالــة للمدعــي وكالــة األجــرة احملكــوم بهــا مائتــن وثمانــن ألــف‬\n      ‫ريــال مبوجــب شــيك مســحوب علــى البنــك (‪ ).....‬برقــم ‪ 44524‬يف‬\n      ‫‪1434/2/3‬ه ـ ألمــر وقــف واســتلمه املدعــي وكالــة ألن وكالتــه تخولــه‬\n\n\n‫‪265‬‬\n\f‫اســتالم األجــرة نقــدا أو شــيكا وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا‬\n                     ‫محمد وعلى آله وصحبه وسلم حرر يف ‪1434/4/8‬هـ‬\n‫احلمــد هلل وحــده وبعــد ثــم عــادت املعاملــة مــن محكمــة االســتئناف‬\n‫بشــرح فضيلــة الرئيــس برقــم ‪ 33/123046‬يف ‪1434/6/20‬ه ـ علــى‬\n‫خطــاب رئيــس محكمــة االســتئناف مبنطقــة مكــة املكرمــة برقــم‬\n‫‪ 33123046‬يف ‪1434/06/17‬ه ـ برفقهــا قــرار التصديــق مبوجــب‬\n‫القــرار رقــم ‪ 34236593‬يف ‪1434/06/11‬ه ـ وهــذا نصــه ‪ -:‬احلمــد هلل‬\n‫وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد ‪ :‬فقــد جــرى منــا‬\n‫نحــن قضــاة االســتئناف بالدائــرة احلقوقيــة األولــى مبحكمة االســتئناف‬\n‫مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n‫رئيــس احملكمــة العامــة مبكــة املكرمــة برقــم ‪ 33123046‬وتاريــخ‬\n‫‪1434/5/29‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ القاضــي‬\n‫باحملكمــة العامــة مبكــة املكرمــة واملســجل بعــدد ‪ 34184303‬وتاريخ‬\n‫‪1434/04/10‬ه ـ واملتضمــن دعــوى ‪ ...........‬ضــد‪ ...........‬واحملكــوم فيــه‬\n‫مبــا دون باطنــه ‪ .‬وبدراســة احلكــم وصــورة ضبطــه والئحتــه اإلعتراضية‬\n‫تقــرر باألكثريــة املوافقــة علــى احلكــم ‪ .‬واهلل املوفــق ‪ ،‬وصلــى اهلل علــى‬\n‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ ،‬قاضــي اســتئناف‪ ...........‬ختــم‬\n‫وتوقيــع ‪ ،‬قاضــي اســتئناف‪ ...........‬ختــم وتوقيــع ‪ ،‬رئيــس الدائــرة‪...........‬‬\n‫ختــم وتوقيــع لــي وجهــة نظــر ‪ ،‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n            ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/06/25‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد ‪ :‬فقــد‬\n‫جــرى منــا نحــن قضــاة االســتئناف بالدائــرة احلقوقيــة األولــى مبحكمــة‬\n‫االســتئناف مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن‬\n\n\n                                                                                      ‫‪266‬‬\n\f      ‫فضيلــة رئيــس احملكمــة العامــة مبكــة املكرمــة برقــم ‪33123046‬‬\n      ‫وتاريــخ ‪1434/5/29‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة‬\n      ‫الشــيخ‪ ....‬القاضــي باحملكمــة العامــة مبكــة املكرمــة واملســجل بعــدد‬\n      ‫‪ 34184303‬وتاريــخ ‪1434/4/10‬ه ـ واملتضمــن دعــوى‪ ...........‬ضــد‬\n                                       ‫‪ ...........‬واحملكــوم فيــه مبــا دون باطنــه ‪.‬‬\n      ‫وبدراســة احلكــم وصــورة ضبطــه والئحته االعتراضيــة تقرر باألكثرية‬\n      ‫املوافقــة علــى احلكــم واهلل املوفــق‪ .‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                                           ‫آلــه وصحبــه وســلم ‪،،،‬‬\n\n\n\n\n‫‪267‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":250,"source_page_end":267,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"35b33c6ab7d80ec92978cf3e1a3457ac3b3fcf28589c0ece98f06fe46454474b","normalized_text_hash":"043d444514dd6f8fbfef684c17c9e2a917895163b79f935979ae9cd6495cd478","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p250-34184303"},{"id":"c644db9c-54e7-528c-a134-7f1a48d797a4","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقد -إجارة ارض مدته عشرون عام ا وبناء مصنع -املطالبة بفسخ العقد لعدم استخراج رخصه املصنع -عدم الفسح لعدم موجبه -احلكم برد الدعوى .","document_number":"34188490","case_number":"33635366","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باملدينة املنورة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/15","year":"1434","subject":"عقد -إجارة ارض مدته عشرون عام ا وبناء مصنع -املطالبة بفسخ العقد لعدم استخراج رخصه املصنع -عدم الفسح لعدم موجبه -احلكم برد الدعوى .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/4/15 :‬هـ‬\n                 ‫ُ‬                 ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪34188490 :‬‬\n                    ‫َر ْق ُم الدعوى‪33635366 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n            ‫‪ 34267661‬تاريخه‪1434/7/15 :‬هـ‬\n\n\n‫عقــد ‪ -‬إجــارة ارض مدتــه عشــرون عام ـ ًا وبنــاء مصنــع ‪ -‬املطالبــة‬\n‫بفســخ العقــد لعــدم اســتخراج رخصــه املصنــع ‪ -‬عــدم الفســح لعــدم‬\n                                        ‫موجبــه ‪ -‬احلكــم بــرد الدعــوى ‪.‬‬\n\n\n\n             ‫‪ -1‬قول اهلل تعالى‪ (( :‬يا أيها الذين آمنوا أوفوا بالعقود))‪.‬‬\n        ‫‪ -2‬املادة (‪ )178‬من نظام املرافعات الشرعية ولوائحه التنفيذية‪.‬‬\n\n\n\n\n‫ادعــى املدعــي بأنــه أجــر علــى املدعــى عليــه األرض املوصوفــة يف‬\n‫الدعــوى للمــدة احملــددة يف دعــواه لغــرض إنشــاء مصنــع وأنــه مضــت‬\n‫مــدة طويلــة مــن تاريــخ توقيــع العقــد ولــم يقــم املدعــى عليــه باســتخراج‬\n‫رخصــة إنشــاء وتشــغيل للمصنــع‪ ،‬ولــذا فقــد طلــب فســخ العقــد وإخــاء‬\n‫األرض وتســليمها لــه‪ ،‬أقــر وكيــل املدعــى عليــه بالعقــد ودفــع بأنــه مت‬\n‫إنشــاء املصنــع وأن موكلــه يســعى يف اســتخراج رخصــة لــه كمــا دفــع‬\n‫بــأن العقــد ال يلــزم موكلــه باســتخراج الرخصــة أو اإلخــاء يف حــال‬\n‫عــدم اســتخراجها‪ ،‬األصــل ســريان عقــد اإلجــارة ومــا ذكــره املدعــي ال‬\n‫يوجــب الفســخ‪ ،‬قضــت احملكمــة بــرد دعــوى املدعــي لعــدم اســتحقاقه‬\n‫مــا يطالــب بــه‪ ،‬قنــع املدعــى عليــه باحلكــم وعــارض عليــه املدعــي‪،‬‬\n\n                                                                                    ‫‪268‬‬\n\f                           ‫قــررت محكمــة االســتئناف املوافقــة علــى احلكــم‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬القاضــي يف احملكمــة‬\n      ‫العامــة باملدينــة املنــورة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n      ‫رئيــس احملكمــة العامــة باملدينــة املنــورة برقــم ‪ 33635366‬وتاريــخ‬\n      ‫‪1433/11/02‬ه ـ املقيــدة باحملكمــة برقــم ‪ 331940260‬وتاريــخ‬\n      ‫‪ 1433/11/02‬ه ـ ففــي يــوم الثالثــاء املوافــق ‪1433/11/16‬ه ـ افتتحــت‬\n      ‫اجللســة وحضــر فيهــا املدعــي ‪ ........‬ســعودي اجلنســية مبوجــب الســجل‬\n      ‫املدني رقم ‪........‬وادعى على احلاضر معه ‪........‬ســعودي مبوجب الســجل‬\n      ‫املدنــي رقــم ‪........‬بوكالتــه عــن ‪ ........‬ســعودي مبوجــب الســجل املدنــي‬\n      ‫‪........‬الوكيــل الشــرعي عــن أخيــه ‪........‬بالوكالــة الصــادرة مــن كتابــة‬\n      ‫عــدل املدينــة املنــورة الثانيــة بالرقــم ‪ 64171‬وتاريــخ ‪1432/11/4‬ه ـ‬\n      ‫والتــي تخولــه املداعــاة واملخاصمــة وســماع الدعــاوى والــرد عليهــا وإقامة‬\n      ‫ا يف دعــواه‪ :‬أنــي‬\n                        ‫البينــة والدفــع وقبــول احلكــم واالعتــراض عليــه‪ .‬قائ ـ ً‬\n      ‫أجــرت مــوكل احلاضــر معــي ‪........‬كامــل أرضــي الواقعــة يف ‪ ...‬طريــق‬\n      ‫‪ ...‬واململوكــة لــي مبوجــب الصــك الصــادر مــن هــذه احملكمــة برقــم‬\n      ‫(‪ )2/5/29‬وتاريــخ ‪1420/6/25‬ه ـ مــدة عشــرين عام ـ ًا إلنشــاء مصنــع‬\n      ‫خرســانه جاهــزة وبلــك إســمنتي‪ .‬وذلــك مبوجــب العقــد املرفــق باملعاملــة‬\n      ‫الصــادر مــن مكتــب احملامــي ‪........‬برقــم بــدون وتاريــخ ‪1428/12/6‬ه ـ‬\n      ‫واملتضمــن ( بعــون اهلل وتوفيقــه مت يف يــوم األحد املوافق ‪1428/12/6‬هـ‬\n      ‫االتفــاق والتراضــي بــن كل مــن الطــرف األول ‪........‬والطــرف الثانــي‬\n      ‫‪ ........‬وميثلــه الوكيــل الشــرعي ‪ .........‬متهيــد الطــرف األول ميلــك أرض‬\n\n‫‪269‬‬\n\f‫مبوجــب الصــك الشــرعي رقــم (‪ )2/5/29‬يف ‪1420/6/25‬ه ـ الصــادر‬\n‫مــن احملكمــة العامــة باملدينــة املنــورة موضحــه حدودهــا بالصــك وببيــان‬\n‫املوقــع ومســاحتها ثالثــون ألــف ومئتــان وأربعــة وتســعون متــر ًا مربع ـ ًا‬\n‫وتســعة وســتون ســنتمترات وتقــع ‪ ...‬طريــق ‪ ...‬ومبــا أن الطــرف الثانــي‬\n‫يرغــب يف اســتئجار هــذه األرض إلنشــاء مصنــع خرســانه جاهــزة وبلــك‬\n‫إســمنتي ومشــتقاته فقــد مت االتفــاق بــن الطرفــن وهمــا بأهليتهمــا‬\n‫العقليــة املعتبــرة شــرع ًا دون إكــراه أو إجبــار علــى اآلتــي‪ -:‬أوالً‪ :‬يعتبــر‬\n‫ا لبنــوده‪ .‬ثاني ـاً‪:‬‬\n                    ‫هــذا التمهيــد جــزء ال يتجــزأ مــن هــذا العقــد ومكم ـ ً‬\n‫أجــر الطــرف األول الطــرف الثانــي كامــل األرض املوضحــة حدودهــا‬\n‫ومســاحتها بداخــل الصــك واملنــوه عنــه يف التمهيد الســابق لغرض إنشــاء‬\n‫مصنــع للخرســانة اجلاهــزة والبلــك اإلســمنتي ومشــتقاته عليهــا‪ )) .‬أ‪.‬ه ـ‬\n‫ومضــى قرابــة خمســة أعــوام مــن تاريــخ توقيــع العقــد ولــم يقم باســتخراج‬\n‫رخصــة إنشــاء وتشــغيل مصنــع اخلرســانة والبلــك وقــد أشــعرته بثــاث‬\n‫خطابات طلبت فيها من املدعى عليه أصاله ســرعة اســتخراج الرخصة‬\n‫وحتديــد مــدة الســتخراج هــذه الرخصــة أو إخــاء األرض وتســليمها لــي‬\n‫هــذه دعــواي‪ .‬وبســؤال املدعــى عليــه وكالــه عــن دعــوى املدعــي أجــاب‬\n‫قائ ـاً‪ :‬مــا ذكــره املدعــي مــن اســتئجار موكلــي لــأرض لغــرض‬\n‫إنشــاء مصنــع خرســانه جاهــزة وملحقاتهــا مبوجــب العقــد املذكــور يف‬\n‫الدعــوى واملــدة احملــددة فصحيــح ولكــن قــد مت إنشــاء املصنــع وهــو‬\n‫قائــم اآلن يف املوقــع‪ .‬ولكــن بــدون رخصــه ونحــن نســعى يف اســتخراج‬\n‫رخصــه لهــذا املصنــع حالي ـ ًا ولكــن ليــس للمدعــي احلــق بإلزامنــا مبــده‬\n‫معينــه الســتخراج الرخصــة أو اإلخــاء حيــث أن العقــد ال ينــص علــى‬\n‫إلــزام موكلــي باســتخراج الرخصــة أو اإلخــاء يف حــال عــدم خروجهــا‪.‬‬\n\n\n                                                                                      ‫‪270‬‬\n\f      ‫لــذا فليــس للمدعــي احلــق يف مــا طالــب بــه ومــع ذلــك فإنــا ســاعون يف‬\n      ‫اســتخراج الرخصــة هــذه إجابتــي‪ .‬وبعرضــه علــى املدعــي قــال‪ :‬العقــد ال‬\n      ‫ينــص علــى إلزامــه باســتخراج الرخصــة ولكــن بقاء املصنــع دون رخصه‬\n      ‫ـاق علــى مطالبتــي‪ .‬هــذا ما لــدي‪ .‬وبناء‬‫مخالــف ألنظمــة الدولــة لــذا فأنــا بـ ٍ‬\n      ‫عليــه رفعــت اجللســة إلــى يــوم األربعــاء املوافــق ‪1434/2/27‬ه ـ الســاعة‬\n      ‫التاســعة صباح ـ ًا إلحضــار صــك ملكيــة العقــار والتحقــق مــن ســريان‬\n      ‫مفعولــه‪ .‬ويف جلســة اخــرى افتتحــت اجللســة وحضــر فيهــا املدعي وتخلف‬\n      ‫املدعــى عليــه كمــا أبــرز املدعــي صــك ملكيــة العقــار محــل الدعــوى‬\n      ‫الصــادر مــن هــذه احملكمــة برقــم ( ‪ )2/5/39‬وتاريــخ ‪1420/7/2‬ه ـ‬\n      ‫كمــا جــرى االستفســار عــن ســجله وســريان مفعولــه فوردتنــا إفــادة‬\n      ‫رئيــس قســم الســجالت املتضمنــة (( مبطابقــة صــورة الصــك املرفقــة‬\n      ‫برقــم ( ‪ )2/5/39‬يف ‪1420/7/2‬ه ـ علــى ســجلها وجــدت مطابقــه وال‬\n      ‫يوجــد مــا يؤثــر علــى ســريان مفعولهــا)) أ‪.‬ه ـ والنتهــاء الوقــت املخصــص‬\n      ‫رفعــت اجللســة ويف جلســة اخــرى افتتحــت اجللســة وحضــر فيهــا املدعــي‬\n      ‫وحضــر حلضــوره ‪........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n      ‫‪........‬الوكيــل الشــرعي عــن ‪ ........‬ســعودي اجلنســية مبوجــب الســجل‬\n      ‫املدنــي رقــم ‪ ........‬مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل‬\n      ‫الثانيــة باملدينــة املنــورة برقــم ‪ ........‬وتاريــخ ‪1434/4/8‬ه ـ والتــي تخولــه‬\n      ‫املطالبــة وإقامــة الدعــاوي واملرافعــة واملدافعــة وســماع الدعــوى واالقــرار‬\n      ‫واالنــكار والصلــح وطلــب اليمــن ورده وإحضــار الشــهود والبينــات ويف‬\n      ‫هــذا اليــوم جــرى منــي االطــاع علــى عقــد االتفــاق الصــادر مــن ‪........‬‬\n      ‫للمحامــاة بتاريــخ ‪1428/12/6‬ه ـ ونــص احلاجــة منــه (( ثالثـاً‪ -:‬مــدة هــذا‬\n      ‫العقــد عشــرون (‪ )20‬عام ـ ًا اعتبــارا مــن مضــي ســتة أشــهر مــن تاريــخ‬\n\n\n‫‪271‬‬\n\f‫صــدور الرخصــة للمصنــع علــى أن يكــون اســتالم األرض والبــدء يف‬\n‫اإلنشــاء والتعميــر حــال صــدور الرخصــة إذ أن هــذه املــدة أي الســتة‬\n‫األشــهر مــا بــن صــدور الرخصــة وبدايــة العقــد أتفــق عليهــا الطرفــان‬\n‫لتكــون فرصــه للطــرف الثانــي مــن أجــل اإلنشــاء والتعميــر‪ .‬رابع ـاً‪-:‬‬\n‫حــددت قيمــة األجــرة الســنوية مــن قبــل الطرفــن مببلــغ وقــدره مائــه‬\n‫وخمســون ألــف ريــال(‪ )150000‬للعــام الواحــد مــن ســنوات العقــد تدفــع‬\n‫يف الســنة األولــى مــن العقــد حــال صــدور الرخصــة كاملــه ويف األعــوام‬\n‫التاليــة تدفــع يف بدايــة كل ســنه مــن ســنوات العقــد‪ .‬خامس ـاً‪ -:‬التــزم‬\n‫الطــرف الثانــي بدفــع مبلــغ وقــدره خمســون ألــف ريــال وملــرة واحــده‬\n‫حــال دفــع األجــرة وذلــك للمدعــو‪ ........ /‬مقابــل أتعــاب الســعي يف هــذا‬\n‫املوضــوع بــن الطرفــن‪ .‬سادس ـاً‪ -:‬التــزم الطــرف الثانــي بدفــع األجــرة‬\n‫املقــررة أول بــأول كاملــه دون تأخيــر أو مماطلــه‪ .‬ســابعاً‪ -:‬للطــرف‬\n‫الثانــي بنــاء وإنشــاء مــا يــراه مناســب ًا لــه حســب املخططــات ومــا متليــه‬\n‫األنظمــة املوضحــة يف رخصــة املصنــع وال يحــق للطــرف األول املعارضــة‬\n‫فيمــا يقــوم بــه الطــرف الثانــي مــن إنشــاءات يف هــذه األرض وال يحــق‬\n‫لــه التدخــل بــأي شــكل مــن األشــكال‪ .‬ثامنـاً‪ -:‬ال يحــق للطــرف األول‬\n‫بعــد توقيــع هــذا العقــد طلــب أي مســاحة أو جــزء مــن هــذه األرض بتاتـاً‪.‬‬\n‫تاســعاً‪ -:‬مينــح الطــرف األول الطــرف الثانــي مطلــق احلريــة والتصــرف‬\n‫يف فعــل مــا يشــاء يف األرض املذكــورة وخــال فتــرة العقــد العشــرين‬\n‫عام ـ ًا ضمــن شــروط العقــد مــع مراعــاة األنظمــة واللوائــح الســارية يف‬\n‫اململكــة العربيــة الســعودية‪ .‬عاشــراً‪ :‬هــذا العقــد ســاري املفعــول علــى‬\n‫ورثــة الطــرف األول والطــرف الثانــي وليــس لهــم احلــق يف نقــض العقــد‬\n‫إال بعــد انتهــاء مدتــه احملــددة بعشــرين عام ـ ًا ويف حــال قيــام الطــرف‬\n\n\n                                                                                      ‫‪272‬‬\n\f      ‫األول ببيــع األرض أو رهنهــا يخطــر الطــرف األول الطــرف الثانــي‬\n      ‫ويكــون للمشــتري عوضـ ًا عــن الطــرف األول (أي يحــل يف تطبيــق هــذا‬\n      ‫العقــد) حــادي عشــر‪ -:‬يحــق للطــرف الثانــي تأجيــر املصنــع ومرفقاتــه‬\n      ‫للغيــر فتــرة العقــد ويكــون (أي الطــرف الثانــي) مســئو ًال أمــام املالــك‬\n      ‫(الطــرف األول) بدفــع اإليجــار مقدمـ ًا كل ســنه هجريــه بــدون تأخيــر‬\n      ‫أو مماطلــه‪ .‬ثانــي عشــر‪ -:‬جميــع تكاليــف اإلنشــاءات داخــل األرض‬\n      ‫املؤجــرة وتكاليــف رســوم التصاريــح والغرامــات ومــا يترتــب عليهــا وأي‬\n      ‫رســوم تفرضهــا اجلهــات احلكوميــة أو املعنيــة مســئوليه الطــرف الثانــي‬\n      ‫وليــس علــى الطــرف األول أي شــيء منهــا‪ .‬ثالــث عشــر‪ -:‬يف حــال حــدوث‬\n      ‫أي خــاف أو صعوبــات ال قــدر اهلل يف هــذا العقــد يتــم التفاهــم بــن‬\n      ‫الطرفــن والوصــول إلــى تســويه وديــه وإذا تعــذر ذلــك يتــم اللجــوء إلــى‬\n      ‫اجلهــات القضائيــة املختصــة باملدينــة املنــورة‪ .‬رابــع عشــر‪ -:‬بعــد انتهــاء‬\n      ‫مــدة العقــد يخلــي الطــرف الثانــي املوقــع دون أي مطالبــه للطــرف األول‬\n      ‫مالــم يتفقــا علــى جتديــد العقــد فتــرة أخــرى ويســلم املبانــي الثابتــة‬\n      ‫والهناجــر للطــرف األول ســليمه كمــا اســتعد الطــرف الثانــي باحملافظة‬\n      ‫علــى اآلبــار املوجــودة‪ .‬خامــس عشــر‪ -:‬حــرر هــذا العقــد مــن نســختني‬\n      ‫أصليتــن موقعتــن مــن الطرفــن وتســلم كل طــرف نســخه للعمــل‬\n      ‫مبوجبهــا والتــزام باحتــرام بنــوده كاملــه‪ )).‬أ‪.‬ه ـ وبســؤال املدعــي عــن‬\n      ‫صحــة بنــود العقــد قــال كلهــا صحيحــه ولكــن لــم يســتخرج الرخصــة‬\n      ‫حتــى اآلن ‪ .‬فأطلــب فســخ العقــد وإخــاء املوقــع حــا ًال هذا مــا لدي ‪ .‬وبعد‬\n      ‫ســماع الدعــوي واالجابــة واالطــاع على عقد التأجيــر ومصادقة املدعي‬\n      ‫علــى صحتــه ودفعــه ببطالنــه لعــدم اســتخراج املدعــى عليــه رخصــه يف‬\n      ‫مزاولــة عملــه التجــاري يف املوقــع وعــدم وجــود مــا يوجــب الفســخ مبثــل‬\n\n\n‫‪273‬‬\n\f‫هــذا الفعــل فاألصــل ســريان عقــد االجــارة ‪ .‬ولقولــه تعالــى‪ (( :‬يــا أيهــا‬\n‫الذيــن أمنــوا أوفــوا بالعقود))اآليــة ‪ .‬وبعــد االطــاع علــى صــك ملكيــة‬\n‫العقــار وســريان مفعولــه لصاحبــه حســب مــا هــو مــدون بعاليــه ‪ .‬بنــاء‬\n‫عليــه فقــد حكمــت بــرد دعــوى املدعــي لعــدم اســتحقاقه مــا يطالــب بــه‪.‬‬\n‫وبعــرض احلكــم علــى املدعــى عليــه قــرر القناعــة بــه ‪ .‬ولــم يقنــع املدعــي‬\n‫وطلــب رفــع احلكــم الــى محكمــة االســتئناف ‪ ،‬واســتعد بتقــدمي الئحــة‬\n‫اعتراضيــة فأجيــب لطلبــه ‪ ،‬وأفهــم بــأن لــه اســتالم نســخه مــن احلكــم‬\n‫يف هــذا اليــوم ‪1434/4/10‬ه ـ وأنــه متــى مضــى ثالثــون يومـ ًا مــن اليــوم‬\n‫الــذي يلــي هــذا التاريــخ ‪ ،‬ولــم يســلم الئحتــه االعتراضيــة ‪ ،‬فــإن حقــة يف‬\n‫ا باملــادة (‪)178‬‬    ‫االعتــراض يســقط ‪ ،‬ويكتســب احلكــم القطعيــة عمـ ً‬\n‫مــن نظــام املرافعــات الشــرعية ولوائحــه التنفيذيــة ‪ ،‬ففهــم ذلــك ‪ ،‬وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر‬\n                                                                 ‫يف ‪1434/4/10‬ه ـ‬\n‫أمــا‬\n   ‫الســام علــى مــن ال نبـ َّـي بعــده ‪َّ ...‬‬‫الصــاة و َّ‬‫احلمــد هلل وحــده‪ ،‬و َّ‬\n‫الشــيخ ‪ ، ........‬القاضــي‬   ‫ـدي أنــا ‪ ، ........‬القائــم بعمــل فضيلــة َّ‬‫بعــد‪ :‬فلـ َّ‬\n‫العامــة يف املدينــة املنـ َّـورة‪ .‬يف يــوم االثنــن ‪1434/08/08‬هــ‪،‬‬  ‫َّ‬       ‫باحملكمــة‬\n‫صباحــا‪ُ ،‬فت َِحـ ْـت اجللســة و كانــت قــد عــادت‬      ‫ً‬         ‫الســاعة العاشــرة‬    ‫َّ‬\n‫املكرمــة باخلطــاب رقــم‬  ‫َّ‬      ‫مبكــة‬\n                                       ‫َّ‬      ‫املعاملــة مــن محكمــة االســتئناف‬\n‫مرفقــا بهــا الصــك رقــم‬      ‫ً‬         ‫(‪ )332149600‬يف ‪1434/07/23‬هــ‪،‬‬\n‫الصــادر مــن‬ ‫(‪ )34188490‬يف ‪1434/04/15‬هــ‪ُ ،‬مظ َّهـ ًـرا بالقــرار َّ‬\n‫ُقوقيــة الثَّالثــة برقــم (‪ )34267661‬يف ‪1434/07/15‬هــ‪،‬‬                 ‫الدائــرة احل َّ‬   ‫َّ‬\n‫ـص احلاجــة منــه‪« :‬بدراســة احلكــم‪ ،‬و صــورة ضبطــه‪،‬‬             ‫واملتضمــن مــا نـ ُّ‬\n                                                                                     ‫ِّ‬\n‫االعتراضيــة تقـ َّـررت املوافقــة علــى ا ُحلكــم» ا‪.‬هــ‪ .‬قاضــي‬\n                                                              ‫َّ‬                  ‫و الئحتــه‬\n\n\n                                                                                                 ‫‪274‬‬\n\f      ‫اســتئناف ‪« ِ ........‬ختــم وتوقيــع»‪ .‬قاضــي اســتئناف‪« ........ /‬ختــم وتوقيــع»‪.‬‬\n      ‫ـرت بإحلاقــه بســجلِّه‬\n                          ‫الدائــرة‪« ........ /‬ختــم و توقيــع»؛ لــذا فقــد أمـ ُ‬\n                                                                               ‫رئيــس َّ‬\n      ‫صباحــا‪ ،‬و‬\n              ‫ً‬      ‫الســاعة (‪)10:00‬‬   ‫كامل َّتبــع‪ ،‬و ُحـ ِّـرر يف ‪1434/08/08‬هــ‪َّ ،‬‬\n      ‫محمــدٍ ‪ ،‬و علــى آلــه و‬\n                            ‫َّ‬    ‫نبينــا‬\n                                      ‫بــاهلل ال َّتوفيــق‪ ،‬وص َّلــى اهلل و س ـلَّم علــى ِّ‬\n                                                                      ‫صحبــه أجمعــن‪.‬‬\n\n\n\n\n‫‪275‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"612f1ba9-3f27-52bc-993f-69d3ecdc8564","source_page_start":268,"source_page_end":275,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"70196d29757331aec7e42169c6430a2fa37babdf7c6abf368a3946a8dd5023ff","normalized_text_hash":"6008a0205e78f6aeecacc103558c4c6a02113837cf131363bb7296293e4f942a","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v7-p268-34188490"}]$archive_payload$::jsonb) AS x LIMIT 25
